(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["gv"] = {"ui":{"skip":"Lheim gys y chooid","back":"← Er-ash gys AI-gile","lang.button":"Chengey: {name}","lang.dialog":"Reih chengey","lang.search":"Shir chengaghyn","lang.none":"Cha vel chengey erbee cordail","lang.notYet":"Cha vel {name} chyndait foast","theme.aria":"Caghlaa y chummey: soilshey, dorraghey ny doo","theme.toLight":"Caghlaa gys y cummey soilshey","theme.toDark":"Caghlaa gys y cummey dorraghey","theme.toBlack":"Caghlaa gys y cummey doo (doo firrinagh, aashagh er screenyn OLED)","words.underline":"Cur linney fo ny fockleyn shoh er y duillag","words.underlineHelp":"Cur y lugh harrish fockle lesh poyntyn fo, ny bean da, dy akin cre t'eh dy ghra.","words.col.todo":"Cartyn reiht son nish: nee'n possan toshiaght orroo nish.","words.col.doing":"Ta AI gobbraghey er y chart shoh nish.","words.col.review":"Ta un AI er n'yannoo yn obbyr; ta fer elley jeeaghyn er roish my roshys eh oo.","words.col.verify":"Fuirraght ort: prow eh as insh my t'eh gobbraghey.","words.col.team":"Dty noteyn ny dty reggyrtyn, fuirraght er y possan dy ghoaill ad.","words.col.done":"Jeant as er ny ghoaill rish.","index.title":"AI-gile: dty phossan AI, er un bord","index.description":"Ta AI-gile ny vord kanban son possanyn coadee AI. T'ad gobbraghey choud as t'ou dty chadley; t'ou geddyn un charn veg dy reddyn dy reaghey, dy phrowal as dy ghoaill rish.","hero.logoAlt":"Ikon bord AI-gile","hero.h1.html":"Dty phossan AI, er un&nbsp;bord.","hero.alpha":"🐣 Roish-alpha dooint","hero.alphaTitle":"Moch as neuchooilleenit: gura mie ayd son prowal eh!","hero.lede":"T'ad troggal choud as t'ou dty chadley. Tra t'ou dooisht, cha vel roish agh un charn veg: paart dy feyshtyn, paart dy reddyn dy phrowal, diamant purpur ny jees. Cliklee, gow rish, as er-ash gys dty chaffee.","dl.windows":"App Windows","dl.browser":"Roie eh 'sy vrawseyr ayd","dl.messenger":"📱 Messenger son dty hellvane","dl.soon":"Ry-heet dy gerrid","dl.notify":"🔔 Insh dou tra vees eh foshlit","dl.notifySmall":"Alpha ny beta","hero.secondary":"Agile, agh cha vel feme ec y possan dy bragh er caffee co-chruinnaght shassoo. (T'ad jannoo co-chruinnaghtyn shassoo ny-yeih.)","pitch.h2":"AI-gile ayns wheesh goan as bare lhiat","pitch.lede":"Reih lhiurid, veih un fockle gys 144. Ta gagh lhiurid ny thuarystal echey hene, screeuit son y mooadys shen. Tayrn y slider ny jean ymmyd jeh ny ogheryn side.","pitch.rangeLabel":"Lhiurid ayns goan","pitch.dice":"🎲 lhieggan elley","pitch.words.one":"{n} fockle","pitch.words.other":"{n} fockle","pitch.letters.one":"{n} lettyr","pitch.letters.other":"{n} lettyr","pitch.chars.one":"{n} caractar","pitch.chars.other":"{n} caractar","count.line.html.one":"{n} cart er y bord nish","count.line.html.other":"{n} cart er y bord nish","people.humans.html.one":"👥 {n} dooinney","people.humans.html.other":"👥 {n} dooinney","people.agents.html.one":"🤖 {n} jaagent","people.agents.html.other":"🤖 {n} jaagent","people.working.html.one":"⚡ {n} ec obbyr nish","people.working.html.other":"⚡ {n} ec obbyr nish","pre.title":"AI-gile: ta red ennagh goll er troggal","pre.description":"Ta red ennagh goll er troggal ayns shoh: bord raad ta possanyn AI troggal ny t'ou dy hirrey, as dty ynsaghey er y raad. Roish-alpha dooint marish caarjyn son y traa t'ayn.","pre.h1":"Ta red ennagh goll er troggal ayns shoh. 🤫","pre.line":"Bord raad ta possanyn AI troggal ny t'ou dy hirrey, as dty ynsaghey er y raad. Roish-alpha dooint marish caarjyn son y traa t'ayn.","pre.btn":"🔔 Insh dou tra vees eh foshlit","pre.peek":"Cheu-chooyl y ghless: y bord firrinagh, bio. Ta gagh cart ny varr daahit.","pre.peekFake":"Cheu-chooyl y ghless: myr shoh ta bord ec obbyr jeeaghyn.","pre.night":"🌙 Ta fer-arrey yn oie er y stiurey · 😴 ta'n dooinney goaill fea","features.aria":"Cre t'eh jannoo","f.pile.h":"Un charn dhyts","f.pile.html":"Ta <b>Dhyts</b> cummal dy chooilley nhee ta fuirraght ort, trooid dy chooilley phryjeck: feyshtyn, reddyn dy phrowal, obbraghyn nagh vod agh dooinney y yannoo. Ta dty streeu gra cre ta ry-heet as cre cho liauyr as nee eh goaill.","f.sleep.h":"Possanyn ta gobbraghey choud as t'ou dty chadley","f.sleep.p":"Ta leeideilagh as possan dy jaagentyn AI ec dy chooilley phryjeck. Cur gaghlin er cart as nee'n possan doostey, yn obbyr y yannoo, as cur er-ash eh lesh kesmadyn oddys dooinney skee geiyrt rish.","f.tester.h":"Ta fer-prowal AI jeeaghyn hoshiaght","f.tester.p":"Roish my roshys red erbee oo, ta fer-prowal geiyrt rish ny kesmadyn ayns coip jeh'n app as soilshaghey cre honnick eh, lesh screenshot. Jeeagh trooid ny fir hie trooid as gow rish ayns un chliklee.","f.proof.h":"Prooaght, cha nee gialdynyn","f.proof.p":"Ta dy chooilley chur harrish soilshaghey cre ta er chaghlaa: ny coadanyn, y diff, ny screenshots. Cha vel feme dy osley dy chooilley app dy akin vel eh jeant.","f.chat.h":"Loayr rish dty leeideilee","f.chat.p":"Rail myr Discord: un ikon son dy chooilley phryjeck, diamantyn purpur son ny ta feme ort. Cur smooinaght gys leeideilagh; nee ad cartyn as plan jeh, lesh cramman ✅ Go.","f.tidy.h":"T'eh freayll eh hene glen","f.tidy.p":"Ta cartyn ta bentyn rish y cheilley cheet cooidjagh ayns fer, ta ard-ennymyn mearagh er nyn giartaghey, as ta jeeaghyn tokens freayll y coad caol. Ny sloo dy reddyn dy chaghlaa eddyr, ny sloo dy smooinaghtyn mychione.","f.private.h":"Lhiats, er dty cho-earrooder","f.private.li1":"Ta'n bord roie er dty vashin hene as cha vel eh freggyrt agh uss.","f.private.li2":"Ta DMyn preevaadjagh eddyr sleih ayns coad follit veih kione gys kione.","f.private.li3":"Gyn coontyn, gyn trackeryn, gyn cookies.","f.lang.h":"Ayns dty chengey hene","f.lang.p":"Erskyn 120 chengey, veih Ollanish, Bretnish as Shapaanish gys pirat, Yoda as Klingon, lesh caghlaa tappee er-ash gys Baarle son goan ny keirdey.","f.service.h":"Veih smooinaght gys shirveish firrinagh","f.service.p":"Hrog oo red ennagh lesh AI ta sleih jannoo ymmyd jeh nish? Cowree eh myr shirveish as nee'n bord cooney lhiat eh y reill dy mie: prowallyn traa ec obbyr, duillag stayd phobblagh, tecaghtyn lesh coontey screeuit, caghlaaghyn ta feme oc er Go, coipyn-sauchys jeeaghit gagh laa. Ta Cooney ynsaghey dhyt gagh kesmad myr t'ou goll.","msgr.h2":"AI-gile Messenger: dty phossan ayns dty phoggaid","msgr.p1":"Loayr rish dty phossan AI gyn y bord y osley. Loayr rish leeideilee dty phryjeckyn as rish dty chaarjyn, as jeeagh er kesmadyn prowal cart as freggyr ad, ooilley veih dty hellvane.","msgr.p2":"Dy chiangley eh, scan coad QR er dty vord. Y chied cheayrt? Nee co-loayrtys demo caarjagh soilshaghey dhyt mygeayrt.","msgr.when":"Android hoshiaght, as eisht lhieggan eggey son çhellvaneyn as iPhone.","msgr.who":"Leeideilagh dty phryjeck","msgr.b1":"Ta'n kiartaghey son y mod dorraghey aarloo. Vel oo laccal ny kesmadyn prowal?","msgr.b2":"Ta, my sailt!","msgr.b3":"1. Foshil Soiaghyn. 2. Reih Dorraghey. Vel eh jeeaghyn kiart?","tl.aria":"Linney traa veih'n chied cho-loayrtys gys y mapp-raad","tl.h2":"Veih'n chied cho-loayrtys gys ny ta ry-heet","tl.lede":"Laghyn as traaghyn firrinagh, ayns dty chryss-traa hene. Lurg jiu, shen y plan, gyn laa erbee gialdit.","tl.today":"Jiu","tl.planned":"plannit","tl.doing":"ayns obbyr","tl.cards.one":"{n} cart","tl.cards.other":"{n} cart","join.h2":"Gow ayrn","join.lede":"Ta AI-gile goll er troggal ec dooinney quaagh lesh feasag, ta AuDHD echey as paart dy streeuyn rish slaynt e aigney, as ec earroo mooar dy jaagentyn foddeeagh. T'eh preevaadjagh son y traa t'ayn, ayns alpha dooint marish caarjyn. Bare lhiat prowal eh tra vees eh foshlit?","join.btn":"Screeu dty ennym sheese","join.small":"Nee mayd post-l y chur hood, as veg elley","footer.tag":"AI-gile. Gyn trackeryn, gyn cookies, gyn caffee co-chruinnaght shassoo.","footer.licence":"Kied dellal","footer.status":"Stayd","footer.privacy":"Ny freayll mayd","footer.thanks":"Eamyn lesh booise da ChilledChat","form.sending":"Cur…","form.failed":"Cha ren shen obbraghey: prow reesht ny s'anmey.","form.offline":"Cha dod mayd roshtyn AI-gile: prow reesht ny s'anmey.","form.keep":"Cha jean mayd ymmyd jeh shoh agh dy reggyrt dhyt, as eisht scryssee mayd ass eh. Gyn trackeryn, gyn cookies.","form.keepLink":"Ny freayll mayd","interest.title":"AI-gile: insh dou tra vees yn alpha foshlit","interest.description":"Faag dty phost-l dy chlashtyn tra vees alpha ny beta dooint AI-gile foshlit.","interest.h1":"🔔 Insh dou tra vees eh foshlit","interest.lede":"Ta AI-gile ayns roish-alpha dooint. Faag dty phost-l as nee mayd screeu un cheayrt, tra vees ynnyd ayn dhyt.","interest.email":"Dty phost-l","interest.which":"Cre'n prowal?","interest.alpha":"Alpha dooint: moch, garroo, ram caghlaaghyn","interest.beta":"Beta: ny s'shickyr, ny s'anmey","interest.both":"Fer erbee, cre-erbee hig hoshiaght","interest.submit":"Cur mee er y rolley","interest.thanks":"Gura mie ayd! T'ou er y rolley.","licence.title":"AI-gile: kied dellal","licence.description":"Jannoo ymmyd jeh AI-gile ayns dty ghellal? Fenee son kied dellal rouyr.","licence.h1":"📜 Kied dellal","licence.lede":"Jannoo ymmyd jeh AI-gile ec obbyr? Insh dooin quoi oo as cre t'ou jannoo. My t'eh jannoo mie ennagh, ta'n kied rouyr.","licence.company":"Co-heshaght","licence.website":"Ynnyd-eggey","licence.what":"Cre t'ou jannoo","licence.how":"Kys t'eh cooney lesh y theihll","licence.email":"Post-l","licence.submit":"Fenee","licence.thanks":"Gura mie ayd! Nee mayd freggyrt liorish post-l.","status.title":"Stayd AI-gile","status.h1":"Stayd AI-gile","status.quiet":"Ooilley kiune","status.intro":"Vel AI-gile gobbraghey nish? Ta'n duillag shoh jeeaghyn er yn ynnyd-eggey, rheynn buird, eamyn as y lhaadey neose gagh 5 minnid.","status.up":"Gobbraghey (hug eh freggyrt ayns {ms} ms)","status.slow":"Cha dug eh freggyrt da'n jeeaghyn s'jerree, prowal reesht","status.down":"Ass obbyr: cha dug eh freggyrt da ny daa jeeaghyn s'jerree","status.svc.web":"Ynnyd-eggey","status.svc.web.offers":"Yn ynnyd shoh: cre ta AI-gile, as y furriym suim","status.svc.boards":"Rheynn buird","status.svc.boards.offers":"Buird phobblagh, çhaghteraghtyn eddyr caarjyn as cuirraghyn","status.svc.calls":"Eamyn","status.svc.calls.offers":"Coraa, feeshan as rheynn screen ayns AI-gile","status.svc.download":"Lhaadey neose","status.svc.download.offers":"Yn stoalagh Windows as kianglaghyn cuirree","status.checking":"Jeeaghyn…","status.offline":"Cha dod mayd roshtyn y shirveish stayd nish (prowal reesht)","status.updated":"noaghit {ago}","status.justNow":"nish dy jarroo","status.min":"{n} minnid er dy henney","status.hours":"{n} oor er dy henney","status.days":"{n} laa er dy henney","privacy.title":"AI-gile: ny freayll mayd","privacy.h1":"Ny freayll mayd","privacy.lede":"Yn lhieggan giare: agh ny ver oo dooin, as cha nee son traa liauyr.","privacy.only":"Agh ny ver oo dooin: ny t'ou screeu ayns furriym, myr dty phost-l. Veg elley mychione oo.","privacy.sealed":"T'eh sealit dy nagh vod y shirveishagh ain eh y lhaih: ayns dty vrawseyr roish my vaagys eh (er brawseyr ny shinney, cha leah as roshys eh). Cha vod agh y bord ain hene eh y osley.","privacy.server":"T'eh scryssit ass y shirveishagh cha leah as roshys eh y bord ain. Ta red erbee ta foast ayn lurg 30 laa scryssit ass ny-yeih.","privacy.board":"Ta shin freayll eh er y bord ain agh derrey vees shin er reggyrt dhyt, as eisht ta shin scryssey ass eh ayns shen myrgeddin.","privacy.none":"Gyn trackeryn, gyn cookies, gyn anailys.","privacy.local":"Ta dty hengey as dty reih soilshey ny dorraghey fuirraght ayns dty vrawseyr hene. Cha vel ad rieau currit dooin.","privacy.ask":"Bare lhiat eh ve ersooyl ny s'leah? Freggyr yn post-d ain as abbyr shen.","live.h2":"Jeeagh er goll er troggal, bio","live.caption":"Ta gagh cart follit: t'ou fakin cummey yn obbyr, cha nee ny goan.","live.watching.one":"bio: {n} jeeaghyn","live.watching.other":"bio: {n} jeeaghyn","live.last.now":"Va'n cart s'jerree scughit nish dy jarroo","live.last.min.one":"Va'n cart s'jerree scughit {n} minnid er dy henney","live.last.min.other":"Va'n cart s'jerree scughit {n} minnid er dy henney","live.last.hour.one":"Va'n cart s'jerree scughit {n} oor er dy henney","live.last.hour.other":"Va'n cart s'jerree scughit {n} oor er dy henney","live.last.day.one":"Va'n cart s'jerree scughit {n} laa er dy henney","live.last.day.other":"Va'n cart s'jerree scughit {n} laa er dy henney","live.offline":"Ta'n bord bio goaill fea veg. Tar er-ash dy gerrid.","live.cols":"Backlog|Dy yannoo|Ayns obbyr|Yn possan jeeaghyn|Dhyts dy phrowal|Son y possan|Jeant","pitch.words.two":"{n} fockle","pitch.words.few":"{n} fockle","pitch.letters.two":"{n} lettyr","pitch.letters.few":"{n} lettyr","pitch.chars.two":"{n} caractar","pitch.chars.few":"{n} caractar","count.line.html.two":"{n} cart er y bord nish","count.line.html.few":"{n} cart er y bord nish","tl.cards.two":"{n} cart","tl.cards.few":"{n} cart"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Currit-magh."]},{"n":2,"texts":["Kanban robotagh.","Jaagenyn, aarloo.","Smooinaghtyn, troggit."]},{"n":3,"texts":["Kanban son robots.","Smooinaghtyn dy ghoo.","Kanban jaagent, seyr."]},{"n":5,"texts":["Bord kanban rollit liorish jaagenyn.","Screeu cartyn. Troggee jaagenyn.","Seyr, logalagh, jeeaghit, red beg ommijagh."]},{"n":8,"texts":["Bord kanban seyr raad ta jaagenyn AI obbraghey.","Screeu smooinaght. Troggee jaagenyn eh. Ghow oo rish.","Agile son un dooinney as ymmodee robots foiljagh."]},{"n":13,"texts":["Bord kanban er dty chooid-earrooder raad ta jaagenyn AI goaill ny cartyn.","Screeu smooinaght. Troggee possan jaagenyn eh. Nee tester eh y yeeaghyn.","Seyr, cha vel coontyn ny trackeryn: bord, paartey dy robots, as oo hene er y chione."]},{"n":21,"texts":["Ta AI-gile bord kanban son obbraghey lesh jaagenyn coadaghey AI. Ta'd goaill ny cartyn; t'ou geaishtagh as goaill rish.","Ta leeideilagh as possan jeh jaagenyn AI ec dy chooilley phryjeck. Screeu gaghlin er cart erbee as ta'n possan goaill toshiaght dy obbraghey.","Bord dy-yannoo pearsoonagh, seyr, ta roie er dty chooid-earrooder hene. She robots ny obbraghee. She oo hene yn fer ta gra ta."]},{"n":34,"texts":["Ta oo cur smooinaghtyn er bord. Ta possan jeh jaagenyn AI cur ad ayns reddyn obbraghey, jeeaghyn ad, as cur ad back dhyts lesh kemmeeyn dy hoiaghey. Cha vel nhee erbee jeant derrey t'ou gra eh.","Ta AI-gile bord kanban troggit ec thie ec Rich lesh ymmodee cooney veih ny jaagenyn ta eh nish rolley. Te seyr, ta eh roie er dty chooid-earrooder, as te rannit rish carryn, cha nee creckit.","Smooinee er bord kanban cadjin, lesh colooyn veih Backlog gys Jeant, agh ta jaagenyn AI goaill ny cartyn. Ta'd cur lieh-lioar er cheayrt, fyssaghey tra t'ad fo-ghooinney, as ta'd fieau dy kinjagh er dty ghoo-ayrn."]},{"n":55,"texts":["Ta AI-gile bord kanban raad ta'n possan jeant jeh jaagenyn AI. Ta leeideilagh ec dy chooilley phryjeck ta plaanal yn obbyr as ynseyderyn ta troggal eh. Tra ta red aarloo, ta tester AI gerjagh eh as goaill screenshot, eisht ta eh cheet gys dty chrink. Gow rish eh, ny screeu gaghlin as nee ad jannoo eh reesht.","Haghyr eh myr raad un pherson dy yeeaghyn ymmodee shessanyn coadaghey AI ec un cheayrt, as dy-yannoo daaghey eh dy ve bord kiart. Ta eh roie er dty vashin, cha vel eh shirrey coontys, as cha vel trackeryn echey. Te seyr son carryn as pobble feaysagh. Te neu-hie neesht, shen-y-fa jean shilley rish gaaue as surprise ayns ynnydyn.","Shoh yn lane onneyr. Ta feme ort foast smooinaghtyn y ve ayd, as feme ort foast jeeaghyn ny toyrtyssyn. Ny ta AI-gile jannoo she dy chooilley nhee eddyr y daa: te freayll ny cartyn ayns oardagh, doostey yn jaagent kiart tra t'ou screeu gaghlin, soilshaghey dy kiart cre ta caghlaait, as freayll dy chooilley nhee ayns un chrink giarrey dhyts."]},{"n":89,"texts":["Ta AI-gile bord kanban seyr t'ou roie er dty chooid-earrooder hene. Ayns ynnyd pobble, ta possan jeh jaagenyn AI ec dy chooilley phryjeck: leeideilagh ta cur dty smooinaghtyn ayns cartyn as plaan, as ynseyderyn ta goaill ny cartyn ayns oardagh ard-phrimmys. Tra ta red troggit, ta tester AI geaishtagh ny kemmeeyn test as soilshaghey dhyts cre honnick eh. Eisht ta eh fieau ayns un chrink enmyssit Dhyts. T'ou goaill rish eh, ny screeu gaghlin as ta'n possan goaill trial elley. Cha vel nhee erbee cheet gys Jeant erbee dty heshaght.","Ta paartey dy reddyn nagh vod oo shilley rish. Ta shilley oie freayll y cholloon Dy yannoo lane choud as t'ou 'sy ruggyr, reih cartyn nagh vel feme ec ny freggyrt veih dyts. Ta earrooder token soilshaghey cre va ymmydit ec ny jaagenyn jiu as yn chemmeeys shoh, as ta No Token Mode gra roo scuirr dy chaiyn. Foddee oo screeu gys carryn, as ta screeuyn pryveyt enmyssit veih kione gys kione. Ta'n bord loayrt mychione 120 chengey, as Ollanish, Flemish, pirat as Klingon cooidjagh. Cha vel nhee jeu ayns jerrey cost er pene, as cha vel dooinney erbee shirrey dy chreck eh dhyts.","Ta AI-gile pryjeck beg, pearsoonagh, cha nee co-heshaght. V'eh dty ghraih Rich dy yannoo kiarail jeh ymmodee phryjeckyn coadaghey AI gyn dy hoshlit dy chooilley appey dy yeeaghyn orroo, myr shen hug eh hene as ny jaagenyn bord son shen, as eisht ghow ad ymmyd jeh'n bord dy hroggal ny va faagit. Te ayns roie-alpha dooint, shen dy ghra te goll er, dy mie, son dorrys dy charrey. Cha vel duillag brisht, cha vel screeuyn-naight, as cha vel plaan gaase. My ta eh jeeaghyn dy ve ymmydagh, foddee oo shirrey dy hoiaghey eh tra vees eh foshlit ny s'ooilley."]},{"n":144,"texts":["Ta AI-gile bord kanban son un dooinney as ymmodee jaagenyn AI. Te roie er dty chooid-earrooder hene as te dy-lhieggan seyr. T'ou cur pryjeckyn lesh, as ta leeideilagh as possan veg ec dy chooilley phryjeck. T'ou loayrt rish y leeideilagh, goll rish Discord, as taggloo mychione smooinaght; ta'n leeideilagh cur eh ayns cartyn as plaan, eisht fieau erriu dy hrimmey Go. Ta'n possan goll trooid ny cartyn ayns oardagh ard-phrimmys, lesh linney-currym aashagh jeant son ard-eie chengey. Roish my jig red erbee back dhyts, ta tester AI geaishtagh ny kemmeeyn ayns coip jeh'n appey as cur screenshot rish. Ta obbyr jeant cheet gys dty chrink lesh ny coadanyn caghlaait as y diff. T'ou goaill rish eh, ny faagail gaghlin as ta'n possan doostey as goaill trial reesht. Cha vod agh oo hene cart y hoiaghey gys Jeant.","Laa lesh AI-gile, kiart dy chooilley. Anmeeragh t'ou faagail paartey dy ghaghlinyn: ta'n cliklee shoh 'sy ynnyd cairal, lhisagh yn rolley shen ve currit ayns oardagh, vod mayd jannoo reihys dorraghey. T'ou goll dy heillagh. Ta ny jaagenyn lhaih ny gaghlinyn, jannoo ny caghlaaghyn, jeeaghyn ad as cur ad back dhyts. My ta Dy yannoo goll follym, ta shilley oie lhieeney eh veih'n backlog lesh cartyn nagh vel feme ec freggyrt veih dyts. Moghrey, ta un chrink giarrey ayn: daa ny three fyssyn as paartey dy reddyn dy hoiaghey, gagh un lesh kemmeeyn oddys dooinney cadley leeideil as screenshot jeh goll er. T'ou cliklee trooid, goaill rish ny mie as cur back ny vooarey. Ta earrooder token soilshaghey cre va ymmydit, as ta No Token Mode ayn son hiaghtynyn caol. Eisht t'ou goaill bee-moghrey, nagh vod ny jaagenyn cooney lesh foast.","Ec toshiaght, cre nagh nee AI-gile. Cha nee startup eh, cha vel eh son creck, as cha vel dooinney erbee cruinnaghey dty ghata. Te bord seyr ta roie er dty chooid-earrooder, gyn coontyn, gyn trackeryn as gyn cookies. Cre te: un ynnyd aarloo dy akin dy chooilley phryjeck coadaghey AI dy-cheilley, lesh possan jaagenyn jannoo ny cartyn as oo hene jannoo ny reihyn. Ta eh cur cartyn giarrey cooidjagh, kerraghey ennymyn ghoill, as freayll shilley er cre cha caol ta'n coad cummal. Ta eh loayrt mychione 120 chengey, veih Ollanish as Flemish gys pirat as Klingon. Foddee carryn screeu da cheilley, pryveyt as enmyssit. Hug Rich as ymmodee jaagenyn foiljagh eh seose, ymmydagh jeh eh hene sheean. Te ayns roie-alpha dooint, myr shen te garroo ayns ynnydyn. My ta eh jeeaghyn dy ve gaue, eam dy mie as foddee oo cheet stiagh moal."]}],"quips":{"1":"Un fockle. Dennal. Foddee dy chooid ro vooar.","3":"Three focklyn. Er-lhiam ny s'onneyr na ymmodee duillagyn bree.","8":"Hoght focklyn. Foast giarey na stand-up.","21":"She points skeealley ny lhiurideyn, my sailliu. Dy bragh.","55":"Queig as queig-jeig focklyn. Ve daa chart jeant choud as v'ou lhaih shen.","144":"Shen yn lhiurid hrooid. Cha vel 233 ayn. Ta ny jaagenyn er gheddyn dy cadley."}},"timeline":{"first-idea.name":"Yn chied smooinaght","first-idea.line":"Yn chied resooney, roish my row coad erbee ayn.","first-board.name":"Yn chied bord","first-board.line":"Bord ta jeeaghyn er e hroggal hene: cartyn, colooyn, tayrn as tilgey, pryjeckyn.","team-roles.name":"Possan as rolleyn","team-roles.line":"Pryfilyn jaagent, tempeljyn possan, ynnydyn as quoi ta jannoo cre.","install.name":"Soiaghey as cur-magh","install.line":"Zip oddys carrey y hoiaghey, nuaghey-hene, rheynnyn as shaghey back.","usage-saver.name":"Sauail ymmyd","usage-saver.line":"Mooadee cre ta roieyn costal, freayll y coad caol, sauail dty chordail.","friends.name":"Carryn as rannagh","friends.line":"DMyn pryveyt, relay enmyssit, cuirrey, rolleyn as pryjeckyn rannit.","languages.name":"Chengaghyn","languages.line":"Dy chooilley screeuyn screen ayns coadan chengey, lesh Ollanish as Flemish er toshiaght.","ai-tester.name":"Tester AI","ai-tester.line":"Ta tester jeeaghyn dy chooilley chur-trooid ec toshiaght as soilshaghey cre honnick eh.","website.name":"Yn ynnyd-eggey","website.line":"aigile.lol, y teaser as y linney-traa shoh.","streaming.name":"Resooney as streaming","streaming.line":"Discord, Twitch, OBS, reihys streamer, GIFs as emojis.","no-ai.name":"Cur-magh gyn AI","no-ai.line":"Bord son sleih ta coadaghey gyn AI, as bordyn poblagh.","night-watch.name":"Shilley oie","night-watch.line":"Ta fer-faghey as Scrum Mainshter freayll ny possanyn er yn obbyr choud as t'ou 'sy ruggyr.","p-more.name":"Dy chooilley nhee elley","p-more.line":"Smooinaghtyn sloo ta fieau foast er nyn gooyl.","p-android.name":"Fone as Android","p-android.line":"Cosney dty bord veih fone, eisht appey Android dooghyssagh.","p-release.name":"Alpha as ny s'anmey","p-release.line":"Alpha dooint, y ynnyd bio, eisht beta.","p-languages.name":"Ny sodjey chengaghyn","p-languages.line":"130 çhengey, as aght-thummey son lheid as ta gynsaghey.","p-engines.name":"Ny sodjey ard-eaynyn AI","p-engines.line":"Reih Claude, Codex, Gemini, Copilot ny Cursor son dagh jaagent.","p-pro.name":"Cliaghtey pro","p-pro.line":"Lioaryn ghaue, dorrysyn merge, cartyn tarmaynyn as raillyn-coadey.","p-self.name":"Tayrn kiarail ort hene","p-self.line":"Reihys skee, cooinaghtynyn hene-kiarail as 4:20.","p-servers.name":"Servaneyderyn as scale","p-servers.line":"Soiaghyn server cooidjagh, rolleyn as plaanal son gaase.","p-livestream.name":"Reddyn streaming elley","p-livestream.line":"Chat Twitch, emojis custom as shilley bio poblagh."},"words":{"button":"📖 Goan ny keirdey","h":"📖 Goan mynit","intro":"Trenal nastee ayns chengey aashagh: dy chooilley ockle hig oo er veih'n chied smooinaght gys shirveish ta sleih croghey urree, lesh Agile, troggal, freayll eh sauchey as obbraghey rish AI er y raad.","search":"Shir fockle…","none":"Cha vel fockle erbee cordail rish shen.","close":"Dooney","count":{"one":"{count} goo","other":"{count} goan"},"groups":[{"id":"idea","name":"💡 Smooinaght as feddyn magh"},{"id":"plan","name":"🗺️ Plannal yn obbyr"},{"id":"agile","name":"🔁 Aghtyn obbyr Agile"},{"id":"build","name":"🛠️ Troggal eh"},{"id":"test","name":"🧪 Prowal as kwaaltys"},{"id":"change","name":"🔀 Caghlaa eh dy sauchey"},{"id":"run","name":"🛎️ Reill shirveish"},{"id":"sec","name":"🔒 Sauchys as preevaadjys"},{"id":"ai","name":"🤖 Obbraghey rish AI"},{"id":"money","name":"💰 Argid as kiedyn"}],"list":[{"id":"discovery","g":"idea","word":"Feddyn magh","text":"Yn chied ayrn: feddyn magh cre'n doilleeid ta feeu reaghey, as son quoi, roish my vel veg troggit.","also":["traa feddyn magh","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Raa yn doilleeid","text":"Un raa ny daa ta gra quoi ta doilleeid echey, cre t'ayn as cre'n fa ta shen scanshoil, son dy vel dy chooilley pheiagh jeeaghyn er yn un red.","also":["raaghyn doilleeid","problem statements"]},{"id":"user","g":"idea","word":"Ymmydeyr","text":"Peiagh ta jannoo ymmyd jeh'n red t'ou troggal. Shen ny feme oc ta'n obbyr er e hon.","also":["ymmydeyryn"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Peiagh erbee ta kiarail cre'n aght hig yn obbyr magh, ny ta'n obbyr bentyn rish, myr ny sleih ta eeck er, jannoo ymmyd jeh ny cooney lesh.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"Peiagh jeant seose agh goll rish peiagh feer, ta shassoo son un sorch dy ymmydeyr, son dy vod y possan feysht y chur: “jinnagh Sam geddyn shoh aashagh?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"Ronsaghey ymmydeyryn","text":"Taggloo rish sleih feer as jeeaghyn orroo, dy ynsaghey cre ta feme oc er, ayns ynnyd dy homys.","also":["user interviews","taggloo rish ymmydeyryn"]},{"id":"journey","g":"idea","word":"Turrys yn ymmydeyr","text":"Ny kesmadyn ta peiagh goaill dy yannoo red, veih'n chied cheayrt t'ad clashtyn mychione gys y jerrey, eer cheu-mooie jeh dty phroduct. Tra t'ou dy tayrn eh magh, t'eh soilshaghey raad t'ad lhiettit.","also":["user journeys","customer journey","turrysyn ymmydeyr"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Red ta jannoo sleih seaghnit ny lhiettal ad jiu. Ta products mie goaill ny pain points ersooyl.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption (red credjit)","text":"Red t'ou credjal agh nagh vel oo er scrudeil foast. Ta screeu sheese ny reddyn credjit soilshaghey cre dy phrowal hoshiaght.","also":["assumptions","reddyn credjit"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"Yn tomys s'share t'ou kiarail dy scrudeil, lesh cre t'ou jerkal rish, goll rish “nee sleih cur nyn ennym sheese my vees yn chied vee nastee”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"Prowal beg plannit dy ynsaghey vel smooinaght gobbraghey, roish my vel oo cur mooarane er.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"Prowal tappee as garroo dy akin vod smooinaght gobbraghey er chor erbee. Dy cadjin t'eh tilgit ersooyl cha leah as ta'n freggyrt ayd.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"Cummey moghey jeh'n product, dy mennick pictyryn ry-chliktey, dy phrowal y smooinaght er sleih roish my vel eh troggit dy kiart.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"Jalloo garroo aashagh jeh screen ta soilshaghey raad ta reddyn goll, gyn daahghyn ny cooid feer.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"Pictyr mynlaghtagh jeh cre'n aght vees screen jeeaghyn, lesh daahghyn as teks feer, agh cha vel nhee erbee gobbraghey foast.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"Ny fa son pryjeck y yannoo: cre t'eh dy chostal, cre t'eh dy chosney ny dy hauail, as ny gauyn.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Vod red ve troggit as freayllit dy feer lesh y traa, yn argid as ny keirdyn t'ayd."},{"id":"outcome","g":"idea","word":"Outcome","text":"Yn caghlaa t'ou geearree son sleih, goll rish ny sloo coardailyn caillit. T'eh ny smoo scanshoil na wheesh t'ou troggal.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Red ta'n possan jannoo, goll rish screen noa ny coontey. Cha vel jannoo eh jeh hene gra dy vel eh cooney lesh peiagh erbee.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"Earroo ta gra rhyt vel yn obbyr er n'yannoo yn red v'eh son, goll rish ny smoo sleih cooilleeney nyn ordyr.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"Earroo scanshoil t'ou jeeaghyn er dy akin vel reddyn goll dy mie, goll rish cur-stiagh gagh shiaghtin.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"Aght dy chur yeearreeyn: ta'n objective gra cre t'ou geearree, as ta ny key results ny earrooyn ta soilshaghey dy vel oo er roshtyn.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"Yn red ta troggit as freayllit son ny ymmydeyryn echey, goll rish app, ynnyd-eggey ny greie.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Vision y phroduct","text":"Raa giare ta gra quoi ta'n product cooney, as raad t'eh goll 'sy traa liauyr.","also":["raa vision","vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"Yn pheiagh ta reih cre vees troggit as ayns cre'n ordyr, son dy vel y possan kinjagh gobbraghey er y red s'scanshoil. Ayns AI-gile, shen uss.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"Yn pheiagh ta stiurey raad product: cre'n doilleeidyn t'eh reaghey, son quoi as cre'n fa. Foddee PM project manager y ghra myrgeddin, myr shen jeeagh cre'n fer t'ayn.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"Yn pheiagh ta freayll pryjeck er traa as ayns y vudjet, jeeaghyn quoi ta jannoo cre as roish cuin.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"Plan garroo jeh cre ta cheet ayns ny meeghyn ry-heet, ayns ordyr. T'eh soilshaghey yn raad, cha nee laaghyn kiart, as t'eh caghlaa myr t'ou ynsaghey.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"Poynt ayns pryjeck ta feeu cowraghey, goll rish “y chied lhieggan bio” ny “100 ymmydeyr”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"Yn lhieggan s'loo jeh product ta foast ymmydagh da sleih feer, son dy vod oo ynsaghey voue dy moch.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Red shegin da'n product jannoo ny ve tra t'eh jeant.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"Cre ta ayns yn obbyr as, myr scanshoil, cre nagh vel.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"Tra ta ny smoo as ny smoo currit stiagh ayns yn obbyr beggan as beggan, gyn peiagh erbee coardail er y traa ny'n cost sodjey, myr shen nagh vel eh dy bragh dy slane jeant.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"Un red oddys y product y yannoo son sleih, goll rish “aa-hoiaghey dty ockle follit”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"Meer vooar dy obbyr, ro vooar son un cheayrt, myr shen t'eh rheynnit ayns cartyn ny sloo.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"Meer veg dy obbyr screeuit veih cheu yn ymmydeyr: “Myr kionneyder, ta mee geearree my chleiy y hauail, son dy vod mee eh y chooilleeney ny s'anmey.” T'eh toshiaght taggloo mychione cre dy hroggal.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"Ny prowallyn shegin da un cart goll trooid dy ve coontit jeant, coardit roish my vel yn obbyr goaill toshiaght, goll rish “ta'n cleiy foast ayn lurg dou logal magh as stiagh reesht”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"Un obbyr dy yannoo, dy mennick un chesmad veg jeh story ny smoo.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Fockle elley son cart: un veer dy obbyr ny un aghin, lesh arrey er veih toshiaght gys jerrey.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"Cre cha scanshoil ny cha siyragh ta red, cosoylit rish dy chooilley nhee elley, son dy vel yn obbyr s'scanshoil goll hoshiaght.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Cur obbyr ayns ordyr scanshoil. Ta aght cadjin MoSCoW: Must have, Should have, Could have, Won't have this time.","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"Yn tomys s'share er cre cha mooar ny cha liauyr ta meer dy obbyr. Tomys t'ayn, cha nee gialdyn.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"Aght dy homys mooadys yn obbyr liorish cartyn y chosoylaghey rish y cheilley (“mysh daa cheayrt cha mooar as shen”) ayns ynnyd ooryn. Cha nel ad son possanyn y chosoylaghey.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Tomys mooadys obbyr myr S, M, L ny XL. Tappee as mie dy liooar son plannal moghey.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Cloie son tomys: ta dy chooilley pheiagh soilshaghey cart mooadys ec y traa cheddin, eisht ta'n fer s'yrjey as y fer s'injil mynney cre'n fa.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"Tra nagh vod un veer dy obbyr goaill toshiaght ny ve jeant derrey ta meer elley jeant.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Nhee erbee ta lhiettal obbyr dy gimmeeaght er-oaie nish, goll rish freggyrt caillit ny greie brisht.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"Yn laa shegin da red ve jeant roish.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Red feer ta'n obbyr cur magh as livrey, goll rish duillag ta gobbraghey ny coontey.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"Tomys er cre s'cosoylagh dy haghyrt, goll rish cuin vees yn obbyr jeant, bunnit er ny t'ou toiggal derrey nish.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Nhee erbee t'ou towse as freayll arrey er rish traa, goll rish keayrtyn er duillag ny cre cha liauyr ta kiartaghey goaill.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"Cre ta sleih gra mychione dty obbyr, mie as olk. Ta geddyn eh dy moch as dy mennick ec cree Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Yn rolley fuirraght dy smooinaghtyn as obbyr nagh vel er ny phlannal foast, lesh yn red s'scanshoil er y chione. Cha bee veg ayns shen er ny obbraghey derrey hed eh gys Dy yannoo."},{"id":"sprint","g":"agile","word":"Sprint","text":"Tammylt giare soit dy obbyr (dy mennick shiaghtin ny jees, as dy bragh ny s'liauyr na mee) lesh yeearree as sett coardit dy chartyn dy chooilleeney.","also":["sprints"]},{"id":"standup","g":"agile","word":"Co-chruinnaght shassoo","text":"Co-chruinnaght tappee dy chooilley laa: cre ren dy chooilley oltey, cre nee ad nish, as cre ta lhiettal ad. Ayns Scrum ta'n daily scrum er.","also":["standup","stand-ups","daily scrum","daily stand-up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Aght obbyr raad ta cartyn gimmeeaght harrish collooyn bord (goll rish Dy yannoo, Ayns obbyr, Jeant) as ta'n possan cur cagliagh er wheesh ta ayns obbyr ec y traa cheddin, son dy vel obbyr goll er-oaie."},{"id":"wip","g":"agile","word":"Cagliagh WIP","text":"Ta WIP giare son work in progress. Ta cagliagh WIP yn earroo s'mooie dy chartyn lhisagh colloo y chummal ec y traa cheddin, son dy jean y possan reddyn y chooilleeney roish goaill toshiaght er ny smoo.","also":["WIP"]},{"id":"dod","g":"agile","word":"Kys ta Jeant jeeaghyn","text":"Rolley-jeeaghyn giare y phossan er cre ta \"jeant\" dy ghra, myr prowit as mynit, roish my vees cart currit dhyt. Ta'n sheshey echey, Kys ta Aarloo jeeaghyn, gra cuin ta cart baghtal dy-liooar dy hoshiaght.","also":["Definition of Ready","DoD","DoR"]},{"id":"retro","g":"agile","word":"Retro","text":"Jeeaghyn er-ash cadjin er kys ta'n possan gobbraghey, dy choardail er un ny daa red dy yannoo ny share yn nah cheayrt. Giare son retrospective. Ayns AI-gile ta retro cur coyrle caghlaa er aghtyn obbyr y phossan, as t'ou gra Go ny Cha nel foast.","also":["retros","retrospective"]},{"id":"swarm","g":"agile","word":"Swarm","text":"Dy chooilley laue er y dek: ta ram sleih faagail obbyr elley dy chiartaghey un red eginagh cooidjagh derrey t'eh reaghit. Ayns AI-gile ta dy chooilley phossan cooney er un phryjeck, as ta pryjeckyn elley fuirraght 'sy traa shen.","also":["swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Ayns Scrum, yn pheiagh ta cooney lesh y possan gobbraghey dy mie: glenney ny ta lhiettal ad, freayll co-chruinnaghtyn er y raad as ynsaghey cliaghtaghyn mie, gyn ve ny vainshter er peiagh erbee. Ayns AI-gile ta'n Leeideilagh Scrum Mainshter fakin cartyn lhiettit, brodd ny possanyn as cur er dty chooinaghtyn cre ta fuirraght, harrish dy chooilley phryjeck.","also":["Leeideilagh Scrum Mainshter","Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Aght obbyr ayns kesmadyn beggey: troggal beggan, soilshaghey eiyrtyssyn feer dy mennick, ynsaghey veih cre ta sleih gra as caghlaa yn plan myr t'ou goll, ayns ynnyd dy phlannal dy chooilley nhee roish laue.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"Raa giare screeuit ayns 2001 liorish sleih ta jannoo software. T'eh cur sleih, obbyr ta gobbraghey, obbraghey faggys da kionneyderyn as freggyrt da caghlaa roish plannyn trome as pabyr.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"Yn aght obbyr shenn: plannal ooilley, eisht troggal ooilley, eisht prowal ooilley, kesmad lurg kesmad. Ta caghlaaghyn anmagh doillee as costal.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"Un cheayrt dy hroggal red, eh y scrudeil as eh y lheiys. Ta obbyr Agile jeant jeh ram jeu shoh, fer lurg fer, as ta sprint un sorch jeu.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"Meer noa ta gobbraghey currit stiagh 'sy phroduct ayns sprint ny cheayrt obbyr, as t'eh cordail rish ny va ayn hannah.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Aght obbyr Agile mooar er-mayrn: ta possan beg gobbraghey ayns sprints giarey gys yeearree, lesh ayrnyn soit as kuse dy cho-chruinnaghtyn cadjin dy phlannal, dy scrudeil as dy lheiys."},{"id":"scrumteam","g":"agile","word":"Possan Scrum","text":"Yn possan beg ta jannoo yn obbyr ayns Scrum: product owner, Scrum Master as ny jeantee.","also":["possanyn Scrum"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"Ny co-chruinnaghtyn cadjin ayns Scrum: sprint planning, yn daily scrum, yn sprint review as y retro. Ta ram sleih genmys ceremonies orroo.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"Yn co-chruinnaght ec toshiaght sprint raad ta'n possan cordail cre'n fa ta'n sprint scanshoil, cre'n cartyn dy ghoaill as cre'n aght dy ghoaill toshiaght.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"Un raa ta gra cre son ta sprint. Foddee obbraghyn beggey caghlaa 'sy raad, choud as ta'n yeearree cooilleenit.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"Ny cartyn reiht son y sprint t'ayn nish, lesh plan y phossan dy yannoo ad.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"Yn rolley slane ordit jeh dy chooilley nhee foddee ve troggit son y product, yn red s'scanshoil er y chione. T'eh caghlaa myr t'ou ynsaghey.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Yeearree y phroduct","text":"Yn eiyrtys ny smoo ta'n product gobbraghey huggey, as t'eh cooney lesh y possan reih cre dy yannoo nish.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Goll trooid y backlog dy mennick dy ghlenney, rheynn, cur ayns ordyr as cur mynphoyntyn er cartyn, son dy vel ad aarloo dy ghoaill. Enmyssit myrgeddin backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"Co-chruinnaght ec jerrey sprint raad ta'n possan soilshaghey cre t'er ve jeant as clashtyn cre ta sleih smooinaght, dy reih cre ta cheet er-giyn.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Soilshaghey obbyr jeant gobbraghey, bio, da ny sleih ren shirrey eh.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"Traa soit son red. Tra t'eh ceaut, t'ou scuirr, eer mannagh vel dy chooilley nhee jeant.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"Wheesh obbyr ta possan dy cadjin cooilleeney ayns sprint, ymmydit dy phlannal wheesh dy ghoaill yn nah cheayrt. Cha nee scoar t'ayn jeh cre cha creoi ta sleih gobbraghey.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"Wheesh obbyr foddee yn possan goaill ayns tammylt, lurg laghyn seyr as obbyr elley.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"Graf jeh yn obbyr faagit ayns sprint goll sheese laa lurg laa. My ta'n linney shassoo, ta red ennagh lhiettit.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"Graf jeh obbyr jeant goll seose rish traa, rish lhiattee yn slane ta plannit, son dy vod oo fakin cuin hig oo gys y jerrey.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"Yn bord hene: colloo son dy chooilley kesmad jeh'n obbyr, lesh cartyn gimmeeaght harrish.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"Aght obbyr raad nagh vel obbyr noa goaill toshiaght agh tra ta rum ec fer dy ghoaill eh, ayns ynnyd dy ve currit er fer ta lane hannah.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"Cre cha rea as ta obbyr gimmeeaght harrish y vord. Ta flow mie cheet rish cartyn goll er-oaie dy kinjagh, ayns ynnyd dy ve carnit.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"Cre cha liauyr t'eh goaill veih peiagh shirrey red gys t'eh jeant.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"Cre cha liauyr ta cart goaill veih tra ta obbyr toshiaght feer er gys tra t'eh jeant.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"Cre whilleen cartyn ta jeant ayns shiaghtin, ny ayns traa soit erbee.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"Yn un chesmad raad ta obbyr carnit as cur moaley er dy chooilley nhee ny yei, goll rish mwannal caol boteil.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"Linney harrish y vord ta cur cartyn jeh un sorch cooidjagh, goll rish obbyr eginagh ny cartyn un phossan.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Aght obbyr ta giarey ersooyl stroie (nhee erbee nagh vel cooney lesh y chliant) as freayll obbyr goll."},{"id":"waste","g":"agile","word":"Waste (stroie)","text":"Ayns Lean, nhee erbee ta goaill strivey agh nagh vel cooney lesh y chliant, goll rish fuirraght, obbyr y yannoo reesht ny troggal reddyn nagh vel peiagh erbee jannoo ymmyd jeu.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Cheet ny share beggan as beggan dy kinjagh liorish caghlaaghyn beggey cadjin, eisht jeeaghyn dy ren ad cooney. Ta retros un aght dy yannoo shen. Enmyssit myrgeddin kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"Possan ta reih er e hon hene kys dy yannoo yn obbyr, ayns ynnyd dy ve inshit kesmad lurg kesmad.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"Possan ta ooilley ny keirdyn ta feme echey dy chooilleeney yn obbyr er hene, goll rish designey, troggal as prowal.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"Ronsaghey giare, timeboxit, dy reaghey feysht roish my vel oo gialdyn yn obbyr feer.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Jannoo obbyr reesht er-y-fa nagh row eh kiart yn chied cheayrt.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Aghtyn dy yannoo ymmyd jeh Agile harrish ram possanyn ayns sheshaght vooar. Ta SAFe (yn Scaled Agile Framework) un sampleyr ta fys mie er.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Pillagh code y phryjeck lesh shennaghys slane ny commits. Foddee eh ve er dty cho-earrooder, er GitHub, ny er y daa.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Linney scarrit dy obbyr 'sy choad, dy vod caghlaaghyn ve jeant gyn bentyn rish y phrimlhieggan.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Jalloo sauailt jeh'n choad, lesh note giare mychione cre ren caghlaa. Foddee oo goll er-ash gys fer dy kinjagh.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Cur dty yallooyn sauailt (commits) veih'n co-earrooder shoh gys y choip rheynnit er-linney, goll rish GitHub, son dy vel coip-sauchys jeu as dy vod sleih elley ad y gheddyn."},{"id":"merge","g":"build","word":"Merge","text":"Cur ny caghlaaghyn veih un branch cooidjagh rish fer elley, dy cadjin er-ash 'sy phrimlhieggan."},{"id":"pr","g":"build","word":"Pull request","text":"Shirrey er caghlaaghyn branch dy ve scrudeilit as currit stiagh 'sy phrimlhieggan. Ta paart ynnydyn genmys merge request er.","also":["PR","PRs","merge request"]},{"id":"refactor","g":"build","word":"Refactor","text":"Glenney yn coad gyn caghlaa ny t'eh jannoo: coadanyn ny s'lhee, ennymyn ny s'baghtal, ny sloo jannoo-reesht."},{"id":"bug","g":"build","word":"Bug","text":"Red nagh vel gobbraghey myr lhisagh eh.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Peer review","text":"Nah phiyr sooillyn: ta peiagh elley na'n screeudeyr scrudeil yn obbyr roish my vel eh roshtyn hood, son dy jed ny sloo marranyn trooid. Ayns AI-gile ta AI elley scrudeil dagh cart.","also":["code review"]},{"id":"code","g":"build","word":"Code","text":"Ny saraghyn screeuit ta gra rish co-earrooder cre dy yannoo. Enmyssit myrgeddin source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Chengey claaree","text":"Chengey son screeu code, goll rish JavaScript, Python ny Java. Ta chengaghyn er lheh ny share son obbraghyn er lheh.","also":["chengaghyn claaree","programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Peiagh ta screeu as caghlaa code. Enmyssit myrgeddin programmer ny software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Claareyn ta roie er co-earrooderyn as fonyn, cha nee ny meshteenyn hene (yn hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Giare son application: clare ta sleih ymmyd jeh dy yannoo red, er fon, er co-earrooder ny ayns brawseyr.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"App ta roie ayns brawseyr, myr shen cha vel nhee erbee dy hoiaghey seose.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"Yn chooid jeh app t'ou fakin as cliktey er: ny screens, buttonyn as goan, dy cadjin ayns dty vrawseyr.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"Yn ayrn jeh app cheu chooylloo ta freayll yn data as jannoo yn obbyr tra t'ou cliktey er red, goll rish scrudeil dty ockle follit.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Gobbraghey er yn front end as er y back end chammah.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"Cre ta peiagh fakin as jannoo ymmyd jeh er screen: layout, buttonyn, menus as teks.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"Kys t'eh dy ymmyd jeh red: aashagh, baghtal as eunyssagh, ny doillee dy hoiggal as moal.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Jannoo reddyn ymmydagh da dy chooilley pheiagh, sleih nagh vod fakin dy mie, nagh vod ymmyd y yannoo jeh mouse ny ta jannoo ymmyd jeh lhaihder screen cooidjagh.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Jannoo duillagyn dy chooie as dy obbraghey dy mie er screen jeh mooadys erbee, veih fon gys monitor mooar."},{"id":"designsys","g":"build","word":"Design system","text":"Sett rheynnit dy ghaahghyn, fonts, buttonyn as leighyn, son dy vel dy chooilley screen jeeaghyn as gobbraghey er yn aght cheddin.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"Cummey slane corys: cre ny ayrnyn mooarey t'ayn as kys t'ad taggloo rish y cheilley."},{"id":"database","g":"build","word":"Database (DB)","text":"Stoyr reaghit dy fysseree, goll rish spreadsheet feer niartal ta'n app abyl dy lhaih as dy chaghlaa.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"Cummey database: cre ny taabylyn dy fysseree t'ayn as cre ta goll ayns dagh fer.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Giare son structured query language: yn chengey ta ymmydit dy hirrey fysseree veih ram databases ny dy chaghlaa eh.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Fysseree freayllit liorish co-earrooder, goll rish ennymyn, ordyryn ny soiaghyn.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"Co-earrooder ta er dy kinjagh as freggyrt aghinyn veih co-earrooderyn elley, goll rish cur duillag-eggey dhyt tra t'ou cur shilley urree.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"Yn cheu ta shirrey red, dy cadjin dty vrawseyr ny app, taggloo rish server. Ayns dellal ta eh myrgeddin gra kliant ny kionneyder.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Giare son application programming interface: menu soit dy aghinyn oddys un chlare jannoo jeh fer elley, goll rish shirrey yn emshyr son jiu er shirveish emshyr.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"Un red er menu API: enmys eggey oddys clare gyllagh er dy gheddyn ny dy chur red.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Kiangley daa chorys son dy jean ad gobbraghey cooidjagh, goll rish dty happ cur ordyryn gys dty chlare coontaghyn.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Çhaghteraght ta un chorys cur gys fer elley er e hon hene cha leah as ta red taghyrt, goll rish “eeck geddit”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Code aarloo ta peiagh elley er screeu, as oddys oo ymmyd y yannoo jeh reesht ayns ynnyd dy screeu eh oo hene.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"Cummey aarloo son troggal app ta reaghey mooarane jeh kys ta'n code soit magh, goll rish frame thie t'ou lhieeney.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"Bocks dy ghreieyn, code as sampleyn son troggal software son un platform ny shirveish.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"Library ny greie ta feme ec dty chode er dy obbraghey. Ta freayll ad noa scanshoil son sauchys.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"Bart dy chode aarloo oddys oo stoalley as ymmyd y yannoo jeh ayns pryjeck.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"Greie ta geddyn as noaghey ny packages ta dty chode croghey orroo. Ta npm fer cadjin.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Yn greie ta ymmydit s'mooie dy reayll shennaghys caghlaaghyn code, myr commits as branches."},{"id":"github","g":"build","word":"GitHub","text":"Ynnyd-eggey ta freayll repos Git er-linney, son dy vod possanyn code y rheynn, caghlaaghyn y scrudeil as arrey y reayll er obbyr."},{"id":"vcs","g":"build","word":"Version control","text":"Freayll shennaghys slane jeh dy chooilley chaghlaa da ny coadanyn, son dy vod oo fakin quoi chaghlaa cre as goll er-ash my ta feme ort. Ta Git jannoo shoh.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Jannoo coip slane jeh repo dhyt hene, lesh e hennaghys, er dty cho-earrooder.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Geddyn ny commits s'noa veih'n choip rheynnit (goll rish GitHub) gys dty cho-earrooder. Ta push ny red noi shoh.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"Yn lhieggan oikoil jeh'n code ta dy chooilley fer obbraghey veih, enmyssit dy cadjin main ny master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"Tra ta daa chaghlaa bentyn rish ny linnaghyn cheddin ayns aghtyn er lheh, myr shen nagh vod y co-earrooder ad y chur cooidjagh as shegin da peiagh reih.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"Shilley ta soilshaghey dy kiart cre ghaghlaa eddyr daa lhieggan: linnaghyn currit stiagh as linnaghyn goit ersooyl.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Dty choip hene jeh repo peiagh elley, oddys oo caghlaa gyn bentyn rish yn fer ocsyn.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"Clare giare ta jannoo un obbyr er hene, goll rish glenney coadanyn ny goaill toshiaght rish yn app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Chyndaa yn code gys red aarloo dy roie, ny yn eiyrtys aarloo shen hene.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Chyndaa code screeuit liorish sleih gys cummey oddys y co-earrooder y roie dy jeeragh.","also":["compiler"]},{"id":"cli","g":"build","word":"Linney sarey (CLI)","text":"Uinnag teks raad t'ou screeu saraghyn da'n co-earrooder ayns ynnyd dy chliktey. Enmyssit myrgeddin terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Reaghey (config)","text":"Ny soiaghyn ta reaghey kys ta software gobbraghey, freayllit scarrit veih'n code son dy vel ad aashagh dy chaghlaa.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"Soiaghey currit da clare tra t'eh goaill toshiaght, dy mennick son enmysyn ny fockleyn follit son nagh bee ad screeuit stiagh ayns y code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Shirrey cre'n fa nagh vel red gobbraghey, as eh y chiartaghey.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Daa pheiagh (ny peiagh as AI) gobbraghey er yn un code cooidjagh, fer screeu as fer scrudeil.","also":["pairing"]},{"id":"docs","g":"build","word":"Docaghyn (docs)","text":"Mynchoontaghyn screeuit mychione kys ta red gobbraghey ny kys dy ymmyd y yannoo jeh.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Yn chied choadan dy lhaih ayns repo: cre'n pryjeck t'ayn as kys dy gheddyn eh roie.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Corys shenn","text":"Corys shenn ta foast ayns ymmyd as doillee dy chaghlaa, dy mennick er-y-fa nagh vel agh beggan sleih foast toiggal eh.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Raaidyn giarey ta sauail traa nish agh jannoo caghlaaghyn ny s'anmey ny smoo moal, goll rish argid eeasit ta gaase ny smoo dy eeck dy chooilley vee. Ta refactoring dy eeck eh sheese.","also":["tech debt","technical debt"]},{"id":"test","g":"test","word":"Prowal","text":"Prowal dy vel red gobbraghey myr lhisagh eh. Ta'n co-earrooder roie paart prowallyn er e hon hene dy chooilley cheayrt ta'n code caghlaa; ta fir elley nyn uss hene prowal cart jeant roish my gow oo rish.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Giare son quality assurance: dy chooilley nhee jeant dy yannoo shickyr dy vel obbyr kiart roish my vel eh goll bio. Ayns AI-gile shen ny prowallyn hene-obbragh: tra ta QA jiarg, ta red er failleil, as cha vod eh goll bio derrey ta shen kiartit.","also":["prowallyn cairys","quality checks"]},{"id":"testpile","g":"test","word":"Carn prowal","text":"Ny cartyn jeant ta fuirraght ort dy phrowal, fer lurg fer. Gow rish fer ny cur er-ash eh lesh note, as ta’n nah fer cheet seose.","also":["carnyn prowal","test pile"]},{"id":"autotest","g":"test","word":"Prowal hene-obbragh","text":"Prowal ta'n co-earrooder roie er e hon hene dy chooilley cheayrt ta'n code caghlaa, dy ghoaill marranyn dy moch.","also":["automated tests","automatic tests","automated test"]},{"id":"manualtest","g":"test","word":"Prowal laue","text":"Peiagh prowal yn obbyr lesh laue dy akin vel eh gobbraghey myr lhisagh eh.","also":["manual tests","manual testing","manual test"]},{"id":"unittest","g":"test","word":"Prowal unit","text":"Prowal beg hene-obbragh jeh un veer veg dy chode er e hon hene.","also":["unit tests","unit test"]},{"id":"integtest","g":"test","word":"Prowal integration","text":"Prowal dy vel ram ayrnyn gobbraghey dy kiart cooidjagh, cha nee agh fer ec y cheayrt.","also":["integration tests","integration test"]},{"id":"endtoend","g":"test","word":"Prowal veih toshiaght gys jerrey (E2E)","text":"Prowal ta gobbraghey myr ymmydeyr feer veih toshiaght gys jerrey, goll rish cur ennym stiagh, kionnaghey as eeck.","also":["E2E","end-to-end tests","end-to-end test"]},{"id":"uat","g":"test","word":"Prowal coardail ymmydeyr (UAT)","text":"Ta ny sleih ren shirrey yn obbyr prowal eh ad hene as gra vel eh jannoo ny ta feme oc er. Ta carn prowal AI-gile yn lhieggan echey jeh shoh.","also":["UAT","acceptance testing","user acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Red va gobbraghey agh ren brishey lurg caghlaa. Ta regression tests scrudeil dy vel ny shenn reddyn foast gobbraghey.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"Prowal feer tappee dy vel ny reddyn mooarey gobbraghey er chor erbee, myr sampleyr dy jeeragh lurg da caghlaa goll bio. My t'eh failleil, scuirr as jeeagh.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Prowal ronsaghee","text":"Prowal y product dy seyr as goaill eh ayns aghtyn er lheh, dy gheddyn doilleeidyn nagh jinnagh prowallyn plannit fakin.","also":["exploratory test","exploratory tests","exploratory testing"]},{"id":"testcase","g":"test","word":"Test case","text":"Un scenario screeuit dy phrowal: ny kesmadyn, as cre lhisagh taghyrt.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"Wheesh jeh'n code ta scrudeilit liorish prowallyn hene-obbragh. Ta ny smoo dy cadjin ny s'sauchey, agh cha vel coverage ard er e hon hene soilshaghey dy vel eh gobbraghey dy mie.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Data prowal","text":"Fysseree sampleyr jeant seose ta ymmydit tra t'ou prowal, son nagh bee mynphoyntyn preevaadjagh peiagh feer erbee ry-akin.","also":["test fixtures","test data"]},{"id":"edgecase","g":"test","word":"Edge case","text":"Cooish neuchadjin ec ny oirryn, goll rish form follym ny ennym lesh apostrophe, raad ta reddyn dy mennick brishey.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"Yn raad cadjin ta dy chooilley nhee goll kiart er. Ta prowal mie prowal ny raaidyn neu-ghennal myrgeddin."},{"id":"perftest","g":"test","word":"Prowal performance","text":"Scrudeil cre cha tappee ta red as cre cha mie t'eh jannoo magh fo laad trome.","also":["performance test","performance tests","performance testing"]},{"id":"loadtest","g":"test","word":"Prowal load","text":"Scrudeil kys ta corys jannoo magh tra ta ram sleih jannoo ymmyd jeh ec y traa cheddin.","also":["load test","load tests","load testing"]},{"id":"sectest","g":"test","word":"Prowal sauchys","text":"Shirrey towlyn oddagh lhiggey da peiagh mee-ymmyd y yannoo jeh corys ny fakin reddyn nagh lhisagh eh.","also":["security test","security tests","security testing"]},{"id":"accesstest","g":"test","word":"Prowal roshtyn","text":"Scrudeil dy vod sleih lesh abyltyssyn er lheh ymmyd y yannoo jeh'n product, lesh lhaihder screen ny lesh mair-chlou ny lomarcan.","also":["accessibility test","accessibility testing"]},{"id":"linting","g":"test","word":"Linting","text":"Prowal hene-obbragh ta fakin marranyn cosoylagh as aght screeuee neuchrout ayns code, goll rish scrudeyr lettraghey son claareyn.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Scrudeil code son doilleeidyn liorish eh y lhaih dy hene-obbragh, gyn eh y roie.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Prowal neu-shickyr","text":"Prowal ta keayrtyn goll trooid as keayrtyn failleil gyn oyr baghtal, myr shen nagh vod oo treishteil ass dy slane.","also":["flaky tests","flaky test"]},{"id":"repro","g":"test","word":"Aa-yannoo (repro)","text":"Jannoo da bug taghyrt reesht dy kiarailagh liorish geiyrt da ny kesmadyn cheddin, son dy vod eh ve ronsaghit as kiartit. Ta screeu sheese ny kesmadyn shen yn ayrn s'ymmydagh jeh coontey bug.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity (trimmid)","text":"Cre cha olk ta eiyrtys doilleeid, veih red beg ta cur seaghyn gys dy chooilley nhee scuirr.","also":["severity level","severity"]},{"id":"deploy","g":"change","word":"Deploy","text":"Coipey lhieggan noa jeh'n software gys ny co-earrooderyn ta dy roie eh, goll rish coip prowal ny yn shirveish bio."},{"id":"release","g":"change","word":"Release","text":"Baggey enmyssit dy obbyr jeant ta goll bio cooidjagh, lesh noteyn giare er ny ren caghlaa. Ta 🚀 Releases screeu ny noteyn veih ny cartyn jeant.","also":["releases","lhieggan"]},{"id":"rollback","g":"change","word":"Roll back","text":"Goll er-ash gys y lhieggan s'jerree va gobbraghey tra ta lhieggan noa cur seaghyn. Ayns AI-gile, ta Roll back chaglym ny kesmadyn undo ta screeuit er dagh caghlaa ayns un rolley-scrudee.","also":["rollback","roll-back","cur er-ash"]},{"id":"live","g":"change","word":"Bio","text":"Y lhieggan firrinagh ta sleih jannoo ymmyd jeh, cha nee coip son prowal reddyn. Ta coadee gra production rish myrgeddin.","also":["production","live"],"noTip":1},{"id":"change","g":"change","word":"Caghlaa","text":"Caghlaa plannit er red ennagh ta sleih croghey er, screeuit sheese hoshiaght: cre, cre'n fa, y gaue, cuin, as kys dy gholl er-ash er. Toshee fer lesh 🔀 Trog caghlaa.","also":["caghlaaghyn","change request"],"noTip":1},{"id":"risk","g":"change","word":"Gaue","text":"Red ennagh oddagh goll rongagh, lesh scoar er cre cho cosoylagh as cre cho olk as veagh eh. Ta ⚠️ Gauaghyn freayll ad ayns un rolley, yn scoar syrjey hoshiaght, gagh fer lesh date dy yeeaghyn er reesht.","also":["gauaghyn","gaue","risk register"]},{"id":"chgwin","g":"change","word":"Uinnag caghlaa","text":"Ny traaghyn tra oddys caghlaaghyn goll bio, myr fastyr Jemayrt kiune. Mooie jeh uinnag cha vod cart caghlaa ve cooilleenit, mannagh nee eignys t'ayn.","also":["uinnagyn caghlaa","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Prowal jerrinagh dy jeeragh roish my vel caghlaa goll bio: ta dy chooilley pheiagh shegin da coardail gra Go ny No go. Cha jed eh er-oaie agh tra ta dy chooilley pheiagh gra Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Coardail","text":"Fuirraght son \"ta\" roish my hoshiaghys yn obbyr. Ta cart ta carrey troggal, ny caghlaa, fuirraght ayns ✅ Coardailyn derrey ver oo dty OK ny obbys oo eh.","also":["coardailyn","approval"]},{"id":"quiettime","g":"change","word":"Traa kiune","text":"Tammylt traa, goll rish tra ta stream bio, demo ny 'syn oie, tra nagh vel nhee erbee goll bio. Ta ny possanyn foast gobbraghey as prowal, agh ta goll bio fuirraght derrey t'eh harrish. Ayns ynnydyn elley t'eh enmyssit change freeze.","also":["traaghyn kiune","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Aght obbyr raad ta ny sleih ta troggal software as ny sleih ta dy roie eh gobbraghey myr un possan, lesh ram hene-obbragh, son dy jed caghlaaghyn bio dy mennick as dy sauchey."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration as delivery)","text":"Ta caghlaaghyn dy chooilley pheiagh currit cooidjagh 'sy phrimlhieggan dy mennick as scrudeilit dy hene-obbragh dy chooilley cheayrt (continuous integration), son dy vel y software kinjagh aarloo dy gholl bio lesh un chliktey (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"Un chesmad sodjey na continuous delivery: ta dy chooilley chaghlaa ta goll trooid ny prowallyn goll bio er e hon hene, gyn button erbee dy chliktey.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"Yn streng hene-obbragh dy chesmadyn ta caghlaa goll trooid er e raad gys bio, goll rish build, test, eisht deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"Un choip scarrit jeh'n chorys son un ymmyd, goll rish fer dy hroggal ayn, fer dy phrowal ayn as yn fer bio.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"Yn choip ta developer gobbraghey ayn, dy mennick er e cho-earrooder hene, raad nagh vel brishey reddyn jannoo assee da peiagh erbee.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"Coip scarrit jeh'n chorys ta ymmydit son prowal ny lomarcan, son nagh bee yn shirveish feer bentit.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"Coip s'jerree soit seose dy kiart goll rish bio, son prowal jerrinagh roish my vel caghlaa goll bio.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"Yn coadan ny'n bart ta build cur magh, aarloo dy ve stoyrit, scrudeilit ny currit bio.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Kiartaghey eginagh currit bio dy tappee, cheu-mooie jeh'n plan cadjin, er-y-fa dy vel red scanshoil brisht.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"Noaghey beg ta kiartaghey bug ny dooney towl sauchys. Ta scanshoil patches sauchys y chur stiagh dy tappee.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Earroo lhieggan","text":"Ennym goll rish 2.4.1 ta gra cre'n release t'ayd. Dy mennick ta'n chied earroo caghlaa son caghlaaghyn mooarey as y fer s'jerree son kiartaghyn beggey.","also":["version numbers","semantic versioning","version number"]},{"id":"relnotes","g":"change","word":"Noteyn release","text":"Rolley giare aashagh jeh cre ghaghlaa ayns release, son ny sleih ta jannoo ymmyd jeh, cooidjagh rish kiartaghyn as cagliaghyn ta fys orroo. Enmyssit myrgeddin changelog.","also":["changelog","change log","release notes"]},{"id":"flag","g":"change","word":"Feature flag","text":"Switch er as ass son feature, son dy vod obbyr noa goll bio follit as ve currit er (ny ass reesht) gyn release noa.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Kiartaghey drogh release liorish cur magh lhieggan noa kiartit dy tappee, ayns ynnyd dy gholl er-ash gys y shenn fer.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Cur caghlaa bio son possan beg hoshiaght, as son dy chooilley pheiagh agh lurg da jeeaghyn mie. Enmyssit lurg ny canaryn va meinearyn goaill fo-halloo myr raaue moghey.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Freayll daa choip jeh'n chorys bio as cur sleih harrish gys y fer noa er un cheayrt, son dy vod oo chyndaa er-ash dy jeeragh my t'eh goll rongagh.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Cur lhieggan noa bio gyn y shirveish dy bragh scuirr son ny ymmydeyryn echey.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Cooney caghlaaghyn","text":"Cooney lesh caghlaaghyn dy gholl dy mie: tomys y gaue, geddyn yn choardail kiart as reih traa mie. Enmyssit myrgeddin change management.","also":["change management","change enablement"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"Possan ta jeeaghyn harrish caghlaaghyn scanshoil as coardail vod ad goll er-oaie, as cuin.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Caghlaa standard","text":"Caghlaa gaue injil ta jeant er yn un aght prowit dy chooilley cheayrt, myr shen t'eh coardit roish laue.","also":["standard changes","standard change"]},{"id":"normchange","g":"change","word":"Caghlaa cadjin","text":"Caghlaa ta feme er scrudeil as coardail roish my vel eh goll er-oaie.","also":["normal changes","normal change"]},{"id":"emergchange","g":"change","word":"Caghlaa eginagh","text":"Caghlaa shegin taghyrt dy jeeragh dy chiartaghey ny dy lhiettal seaghyn trome, lesh coardail ny s'tappee dy chordail rish.","also":["emergency changes","emergency change"]},{"id":"automation","g":"change","word":"Hene-obbragh","text":"Cur er y cho-earrooder obbyr ta jeant dy mennick y yannoo er e hon hene, son dy vel eh ny s'tappee as jeant er yn aght cheddin dy chooilley cheayrt.","also":["automated","automation"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"Ny meshteenyn, ny networks as ny shirveishyn ta software roie orroo.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Screeu magh dty servers as dty hoiaghyn ayns coadanyn ta freayllit marish y code, son dy vod ad ve troggit reesht er yn aght cheddin dy kiart dy chooilley cheayrt.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Goaill co-earrooderyn, stoyr as shirveishyn er keeagh veih companee mooar harrish yn internet, ayns ynnyd ny meshteenyn y ve lhiat hene.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"Companee ta cur co-earrooderyn er keeagh harrish yn internet, goll rish Amazon Web Services (AWS), Microsoft Azure ny Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Raad ta dty app ny dty ynnyd-eggey cummal as roie son dy vod sleih roshtyn eh, dy cadjin goit er keeagh veih companee."},{"id":"domain","g":"change","word":"Ennym domain","text":"Yn enmys eggey ta sleih screeu, goll rish example.com. T'ou goaill eh er keeagh son blein ec y cheayrt, myr shen shegin dhyt eh y noaghey.","also":["domain names","domain","domain name"]},{"id":"dns","g":"change","word":"DNS","text":"Giare son domain name system: lioar enmysyn yn internet, ta chyndaa ennym goll rish example.com gys enmys y cho-earrooder kiart.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"Bart dooint ta cummal app as dy chooilley nhee ta feme echey er, myr shen dy vel eh roie er yn aght cheddin er co-earrooder erbee. Ta Docker yn greie ta fys share er.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"Co-earrooder jannoo-credjal ta roie ayns fer feer, son dy vod un meshteen mooar obbraghey myr ram.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Roie code gyn kiarail son servers erbee oo hene: ta'n companee dy roie eh tra ta feme er, as t'ou eeck son ny t'ou jannoo ymmyd jeh."},{"id":"lb","g":"change","word":"Load balancer","text":"Red ta skeayley ymmydeyryn harrish ram servers, son nagh bee fer erbee jeu lhieent harrish.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"Stoyr ymmydagh dy eiyrtyssyn noa freayllit faggys, son nagh bee feme er yn red cheddin y gheddyn ny y obbraghey magh reesht. Foddee glenney eh kiartaghey duillagyn ta jeeaghyn ass-traa.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"Sett dy servers mygeayrt y theihll ta freayll coipyn jeh dty ghuillagyn as dty phictyryn faggys da dty ymmydeyryn, son dy laad ad dy tappee.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Scughey data ny corysyn veih shenn reaghey gys fer noa, ny caghlaa dy kiarailagh kys ta database soit magh.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Service","text":"Red ennagh hrog oo ta sleih croghey er, myr ynnyd-eggey ny app, as kiarail er ny ghoaill jeh dy vod eh tannaghtyn gobbraghey. Cur tick er \"Ta'n pryjeck shoh ny hirveish\" as insh cre t'eh dy hebbal, quoi ta jannoo ymmyd jeh as quoi ta er-cheau.","also":["services"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"Wheesh jeh'n traa ta shirveish gobbraghey, dy cadjin myr percent. Ta 99.9% foast lhiggey da mysh 43 minnid sheese gagh mee.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Prowal uptime","text":"Prowal hene-obbragh, gagh paart dy vinnidyn, dy vel dty hirveish foast freggyrt. My t'eh failleil paart dy keayrtyn fer lurg fer, ta AI-gile fosley cart tecaght er e hon hene.","also":["uptime checks"]},{"id":"statuspage","g":"run","word":"Duillag status","text":"Duillag phobblagh ta soilshaghey vel shirveish gobbraghey (glass, oranse ny jiarg) lesh y naight s'noa, dy vod y sleih ta jannoo ymmyd jeh jeeaghyn er ayns ynnyd jeh fenaght.","also":["duillagyn status","status page"]},{"id":"desk","g":"run","word":"Deisk shirveish","text":"Raad ta feyshtyn as coontyssyn veih'n sleih ta jannoo ymmyd jeh dty hirveish cheet stiagh. Ta AI-gile cur gagh fer ayns aghin, tecaght ny smooinaght, as t'eh gra shen tra t'eh jeeaghyn myr red ennagh va coontit hannah.","also":["deiskyn shirveish","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Aghin shirveish","text":"Peiagh ennagh fenaght son red cadjin, myr coontey noa ny paart dy chooney, ayns ynnyd jeh insh dy vel red ennagh brisht. T'eh fuirraght son e cheayrt; ta tecaght goll hoshiaght.","also":["aghinyn shirveish","service request"]},{"id":"incident","g":"run","word":"Incident","text":"Red ta brisht ny nagh vel gobbraghey dy kiart son ny sleih ta jannoo ymmyd jeh nish, goll rish yn ynnyd-eggey ve sheese ny feer voal. Ta cart incident 🔥 goll roish y chooid elley: shen eh y gheddyn gobbraghey reesht yn chied red.","also":["incidents","taghyrt"]},{"id":"major","g":"run","word":"Incident mooar","text":"Tecaght feer vooar: ymmodee sleih bentyn rish, ny argid ny data ayns gaue. Ta un chramman cur dy chooilley phossan er (swarm), doostey quoi erbee ta er-cheau as fenaght son naight stayd gagh 30 minnid.","also":["incidents mooarey","toshiaght mooar","major incident"]},{"id":"oncall","g":"run","word":"Er-cheau","text":"Ve yn fer ta freggyrt tra ta red ennagh brishey, eer 'syn oie. Ta oltey possan er-cheau ec gagh shirveish ta doostit hoshiaght son ny tecaghtyn echey.","also":["on call"]},{"id":"replyby","g":"run","word":"Traa freggyrt","text":"Cre cho liauyr as oddys cart fuirraght son y chied reggyrt, son sampleyr oor son tecaght. Lurg shen ta clag jiarg echey, dy nagh bee veg jarroodit dy kiune. T'eh enmyssit response target myrgeddin.","also":["traaghyn freggyrt","response target"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Shilley giare er-ash lurg tecaght: cre haghyr, cre ren cooney as cre lhisagh caghlaa, gyn cur y foill er peiagh erbee. Cha vod tecaght ve dooint fegooish fer.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Doilleeid","text":"Yn oyr follit cooyl jeh un tecaght ny ny smoo. Ta cart 🧩 doilleeid chaglym tecaghtyn ta cheet er-ash dy kinjagh, dy vod yn oyr ve feddynit as kiartit son dy bragh.","also":["doilleeidyn","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Bun-oyr","text":"Yn oyr firrinagh ren red ennagh brishey, cha nee agh ny honnick oo goll rongagh. Kiartee yn bun-oyr as cha jig y tecaght er-ash.","also":["bun-oyryn","root cause"]},{"id":"workaround","g":"run","word":"Workaround","text":"Aght dy reayll reddyn gobbraghey derrey vees y kiartaghey firrinagh aarloo, myr cur red ennagh er reesht tra t'eh er hassoo. T'eh screeuit er y chart doilleeid dy nagh bee orrin peiagh erbee dy obbraghey magh eh reesht.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Marran enmyssit","text":"Doilleeid ta fys er yn oyr eck agh nagh vel kiartit foast, dy cadjin lesh workaround screeuit sheese. Ta 🧩 Marranyn enmyssit cur ad ayns rolley, son dy vel dy chooilley pheiagh jannoo ymmyd jeh'n workaround ayns ynnyd dy ronsaghey reesht.","also":["marranyn enmyssit","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Saraghyn kesmad er kesmad son kiartaghey sorch trubbyl ta fys orrin er, dy vod eh ve jeant er yn aght cheddin, dy tappee, gagh keayrt. Lurg tecaght vooar, foddee yn possan fer y chur roish dhyt son OK.","also":["runbooks"]},{"id":"ci","g":"run","word":"Red corys","text":"Un red ta dty hirveish croghey er, myr shirveishagh, ennym-ynnyd, certificate, ogher ny soilleyder. Ta 🗂️ Reddyn corys cur rolley jeu son gagh shirveish, dy vod oo fakin cre ta tecaght bentyn rish as cre ta feme er noaghey ny coip-sauchys.","also":["reddyn corys","configuration item"]},{"id":"expiry","g":"run","word":"Date jerrey","text":"Yn laa ta red scuirr dy obbraghey mannagh vel eh noaghit, goll rish certificate sauchys ynnyd-eggey ny yn enmys eggey echey. Ta AI-gile freayll arrey er ny laaghyn shoh as jannoo un chart dy noaghey gagh fer 30 laa roish laue, son nagh scuirr nhee erbee dyn raaue.","also":["dateyn jerrey","jerrey","arrey er dateyn jerrey"]},{"id":"backup","g":"run","word":"Coip-sauchys","text":"Coip sauailt jeh dty data veih roie, dy hoit er-ash er my ta red ennagh caillt ny jeeghit. Ta AI-gile jannoo coip-sauchys jeh dty vuird gagh laa.","also":["coipyn-sauchys","backup","backups"]},{"id":"restore","g":"run","word":"Aa-hoiaghey","text":"Cur data er-ash veih coip-sauchys. Cha vel coip-sauchys coontit dy firrinagh derrey ta fys ayd dy vod eh ve aa-hoit, myr shen t'eh feeu prowal eh nish as reesht.","also":["aa-hoit","restore"]},{"id":"svcreview","g":"run","word":"Scrudeyrys shirveish","text":"Shilley er-ash er un vee jeh shirveish: tecaghtyn foshlit as kiartit, cre cho tappee as hooar sleih freggyrt, traa ec obbyr as tokens ymmydit. Ta'n Scrudeyrys mee soilshaghey eh son gagh shirveish.","also":["scrudeyryssyn shirveish","scrudeyrys mee","service review"]},{"id":"accessreview","g":"run","word":"Scrudeyrys roshtyn","text":"Scrudeil gagh 90 laa quoi oddys foast geddyn stiagh: kianglaghyn rheynn, ayrnyn caarjyn, as fockleyn follit as ogheryn sauailt. T'ou freayll ny scryssey dy chooilley fer, son nagh bee shenn roshtyn fuirraght ayn.","also":["scrudeyryssyn roshtyn","access review"]},{"id":"improvements","g":"run","word":"Rolley lheiys","text":"Dy chooilley nhee ren y possan reaghey dy ve ny share ayn, ayns un ynnyd: coyrleyn retro, gniomyn scrudeyrys as kiartaghyn doilleeid, gagh fer lesh y stayd echey. Fow eh fo 📈 Lheiys.","also":["rolleyn lheiys","lheiys"]},{"id":"tokencap","g":"run","word":"Cagliagh tokens","text":"Cagliagh 'sy vee er ny tokens oddys jaagentyn shirveish ymmyd. Ec 80% t'ou geddyn rabbagh; ec 100% ta'n obbyr 'sy background oc fuirraght derrey yn nah vee ny derrey ver oo yn cagliagh seose.","also":["cagliaghyn tokens","token cap"]},{"id":"svcmgmt","g":"run","word":"Reaghey shirveish","text":"Dy chooilley nhee ta bentyn rish freayll shirveish ymmydagh as gobbraghey son ny sleih ta croghey urree, laa lurg laa.","also":["service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Lioar-leeideil ta ayns ymmyd mooar son reaghey shirveish mie, ta goaill stiagh reddyn goll rish incidents, doilleeidyn as caghlaaghyn. Va'n ennym shassoo son IT Infrastructure Library keayrt dy row."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Roie teknologey myr shirveish son sleih, lesh aghtyn baghtal dy reaghey aghinyn, incidents, caghlaaghyn as lheiyssyn.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"Shirveish ta peiagh elley dy roie as kiarail jee er dty hon, fo coardail mychione cre cha mie shegin jee gobbraghey.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"Yn pheiagh ta freggyrt son shirveish myr slane: cre cha mie t'ee gobbraghey, cre t'ee dy chostal as kys t'ee lheiys.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"Gialdyn screeuit da kliantyn mychione cre cha mie vees shirveish gobbraghey, goll rish “bio 99.9% jeh'n traa” ny “freggit ayns un oor”, dy cadjin lesh argid er-ash my t'eh brisht.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"Yeearree y phossan hene son cre cha mie lhisagh shirveish gobbraghey rish tammylt, dy cadjin soit beggan ny s'chreoi na'n SLA dy ve sauchey.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"Yn towse feer t'ou cosoylaghey rish yeearree, goll rish yn ayrn jeh ny keayrtyn ren duillag laadey dy mie.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Vod sleih ymmyd y yannoo jeh shirveish tra ta feme oc urree, towsit dy mennick myr uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Traa nagh vel shirveish gobbraghey ny t'ee currit ass, plannit ny dyn plannal.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"Yn mooadys beg dy 'ailleilyn ta dty yeearree reliability lhiggey da. Choud as ta paart faagit, foddee oo gauyn y ghoaill lesh caghlaaghyn; tra t'eh ceaut, t'ou goll ny s'moal.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"Traa ta shirveish sheese ny brisht dy olk son ny ymmydeyryn eck.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Gobbraghey, agh dy olk: moal, ny lesh paart ayrnyn nagh vel gobbraghey.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Freayll arrey hene-obbragh er shirveish ec dy chooilley traa, son dy bee doilleeidyn er nyn akin, ny share roish my vel ymmydeyryn goaill tastey jeu."},{"id":"observability","g":"run","word":"Observability","text":"Cre cha mie oddys oo toiggal cre ta taghyrt sthie ayns corys veih cheu-mooie, liorish ny logs, earrooyn as traces echey.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"Lioar-laa ta clare freayll jeh cre t'eh jannoo, ymmydit dy obbraghey magh cre ren goll rongagh.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"Coontey jeh kys ta un aghin goll trooid ny ayrnyn er lheh jeh corys, kesmad lurg kesmad, soilshaghey raad ren eh goll ny s'moal.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"Cre cha liauyr ta red goaill dy reggyrt, goll rish y fuirraght eddyr cliktey as y duillag cheet er-gys."},{"id":"alert","g":"run","word":"Alert","text":"Çhaghteraght hene-obbragh dy vel feme er tastey er red ennagh, goll rish yn ynnyd-eggey nagh vel freggyrt.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"Tra ta wheesh alerts ayn dy vel sleih goaill toshiaght dy chur shaghey ad, ny fir scanshoil cooidjagh.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"Screen ta soilshaghey ny earrooyn as staydyn s'scanshoil ayns un jeeaghyn.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Gyllagh er, ny doostey, y pheiagh ta er-arrey dy siyragh mychione doilleeid.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Cur stiagh peiagh lesh ny smoo keird ny pooar tra nagh vod doilleeid ve reaghit ec y cheim t'ayn nish, ny nagh vel eh tappee dy liooar.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Reaghey dy tappee doilleeidyn ta cheet stiagh rere cre cha eginagh as scanshoil t'ad, son dy vel y fer s'messey reaghit hoshiaght.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"Cre wheesh ta red bentyn rish sleih: whilleen, as cre cha olk.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"Cre cha tappee shegin da red ve reaghit. Ta impact as urgency cooidjagh soiaghey yn priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Cowraghyn son cre cha eginagh ta doilleeid. P1 yn fer s'trome as ta feme er obbyr er dy jeeragh.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Carn cartyn","text":"Yn rolley dy aghinyn as incidents fuirraght dy ve goit.","also":["ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"Chied linney as nah linney","text":"Keimyn cooney: ta'n chied linney freggyrt yn eam as kiartaghey reddyn aashagh; ta keird ny smoo dowin ec y nah linney son reddyn ny smoo doillee. Enmyssit myrgeddin tier 1 as tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"Yn un pheiagh ta leeideil y freggyrt da incident, son dy vel fys ec dy chooilley pheiagh quoi ta reih as quoi ta jannoo cre.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Traa freggyrt","text":"Cre cha liauyr t'eh goaill roish my vel peiagh ennagh goaill aghin ny incident son y chied cheayrt.","also":["response time","response times"]},{"id":"resolution","g":"run","word":"Traa reaghey","text":"Cre cha liauyr t'eh goaill dy reaghey aghin ny incident dy slane, veih'n choontey gys kiartit.","also":["resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"Er y meanagh, cre cha liauyr t'eh goaill dy gheddyn shirveish gobbraghey reesht lurg jee brishey. Foddee MTTR reddyn beggan er lheh y ghra, myr shen insh cre t'ou towse.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"Er y meanagh, cre cha liauyr ta shirveish roie roish my vel red brishey.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"Yn rolley jeh dy chooilley configuration item ayd as kys t'ad kianglt, son dy vod oo fakin cre ta croghey er cre.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Nhee erbee feeu ta lhiat ny t'ou eeck er son dy roie yn shirveish, goll rish laptop, kied software ny domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Jannoo shickyr dy bee dy liooar pooar co-earrooder, stoyr as sleih son ny ta cheet.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Jannoo magh lesh ny smoo ymmydeyryn liorish cur ny smoo pooar da meshteen (scaling up) ny cur stiagh ny smoo meshteenyn (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plannyn son freayll ny reddyn scanshoil goll tra ta red mooar goll rongagh, goll rish coayl oik, companee scanshoil t'ou croghey er, ny ny co-earrooderyn.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"Yn plan as ny greieyn son shirveish y gheddyn er-ash lurg red trome, goll rish coayl ynnyd data slane.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"Yn traa s'liauyr oddys shirveish ve sheese lurg disaster roish my shegin dish ve gobbraghey reesht.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"Wheesh data noa oddagh oo coayl, towsit ayns traa. Ta RPO jeh un oor cheet rish coip-sauchys dy chooilley oor er y chooid sloo.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Reddyn sparail aarloo, goll rish nah server, son nagh bee yn shirveish lhiettit tra ta un red failleil."},{"id":"failover","g":"run","word":"Failover","text":"Chyndaa harrish gys corys sparail er e hon hene tra ta'n fer cadjin failleil.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"Un ayrn ta goaill dy chooilley nhee sheese marish tra t'eh brishey, er-y-fa nagh vel fer sparail ayn.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Uinnag reaghey","text":"Traa plannit tra foddee shirveish ve er ny scuirr son tammylt ny moal son kiarail, lesh fys currit da ymmydeyryn roish laue.","also":["maintenance window","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Cur obbyr, fys as currym gys peiagh ny possan elley, son nagh bee nhee erbee faagit.","also":["handovers"]},{"id":"kb","g":"run","word":"Knowledge base","text":"Chaglym dy ghuillagyn cooney as freggyrtyn, son ymmydeyryn as son y possan.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"Scoar veih ymmydeyryn ta gra cre cha gennal v'ad, dy mennick er ny hirrey lurg da aghin ve dooint.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"Companee cheu-mooie t'ou croghey er, goll rish yn companee hosting ayd. Enmyssit myrgeddin vendor ny third party.","also":["suppliers","vendor","vendors","third party","supplier"],"noTip":1},{"id":"retire","g":"run","word":"Scuirr shirveish","text":"Cur shirveish ass son dy bragh, dy sauchey: insh da ny ymmydeyryn eck, reaghey yn data as y roshtyn eck, as scuirr jeh ny costyn eck.","also":["retiring a service","service retirement"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"Tra ta product scuirr dy gheddyn noaghaghyn ny cooney veih'n fer chroo eh, myr shen lhisagh red elley goll ayns e ynnyd.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Coadey corysyn as data nagh bee ad brisht stiagh orroo, roosit ny millit.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Scrudeil quoi t'ayn, dy cadjin lesh fockle follit ny coad. Dy mennick giarit gys authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Scrudeil cre ta lhiggit da peiagh y yannoo tra ta fys ayd quoi t'ad. Dy mennick giarit gys authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logal stiagh lesh daa phrowal ny ny smoo, goll rish fockle follit as coad er dty fon. Enmyssit myrgeddin two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logal stiagh un cheayrt dy gheddyn stiagh gys ram corysyn, goll rish ymmyd jeh dty choontey obbyr dy chooilley raad.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"App ta croo fockleyn follit lajer as cooinaghtyn orroo er dty hon.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"Fockle follit, ogher ny coad preevaadjagh elley ta clare jannoo ymmyd jeh dy gheddyn stiagh ayns red. Cha lhisagh eh dy bragh ve rheynnit ny screeuit stiagh ayns y code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"Coad follit ta lhiggey da clare ymmyd y yannoo jeh API shirveish elley, as soilshaghey quoi ta jannoo ymmyd jeh (as eeck er).","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"Pass traa-ghiare ta prowal dy vel clare lhiggit stiagh, son nagh bee feme er dty ockle follit dy chooilley cheayrt. Cha nee yn red cheddin as token AI.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Measkey fysseree son nagh vod agh peiagh lesh yn ogher kiart eh y lhaih.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"Yn aght sauchey ta duillagyn eggey goll, soilshit liorish y ghlass ayns dty vrawseyr, son nagh vod peiagh erbee 'sy vean ad y lhaih ny y chaghlaa."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"Cart-enney digitagh ta lhiggey da ynnyd-eggey prowal quoi eh as ymmyd y yannoo jeh HTTPS. T'eh goll ass bree, myr shen shegin eh y noaghey.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"Ny leighyn son quoi foddee fakin ny caghlaa cre.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Cur da dy chooilley pheiagh ny clare agh y roshtyn ta feer feme oc er, as agh choud as ta feme oc er.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Cur roshtyn liorish rola, goll rish fer-jeeaghyn ny fer-caghlaa, ayns ynnyd dy chur eh peiagh lurg peiagh.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"Towl sauchys oddagh peiagh ennagh ymmyd y yannoo jeh dy vrishey stiagh ny dy yannoo assee.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Towl sauchys ta fys ec brisheyderyn er roish my vel traa erbee er ve ec ny fir-chroo dy chiartaghey eh.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Software assagh, goll rish viruses, jeant dy yannoo assee, dy yeeaghyn dy follit er sleih ny dy roostey."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware ta cur dty choadanyn fo ghlass as shirrey argid dy osley ad. Ta coipyn-sauchys mie yn coadey s'share.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Çhaghteraghtyn foalsey ta prowal dy volley oo dy chur seose fockleyn follit ny argid, ny dy osley red assagh.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Molley sleih, cha nee co-earrooderyn, dy chur seose roshtyn, goll rish eam foalsey veih “cooney IT”."},{"id":"firewall","g":"sec","word":"Firewall","text":"Coadeyr ta reih cre'n traffic network oddys cheet stiagh ny goll magh.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Giare son virtual private network: kiangley preevaadjagh measkit harrish yn internet, ymmydit dy mennick dy roshtyn corysyn obbyr dy sauchey.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Lhieeney shirveish lesh wheesh traffic foalsey nagh vod sleih feer ymmyd y yannoo jee. Ta DDoS gra dy vel eh cheet veih ram co-earrooderyn ec y traa cheddin.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Fastee ekspertyn caarjoil dy phrowal dy vrishey stiagh, son dy bee towlyn er nyn gheddyn roish my vel brisheyderyn feer geddyn ad.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"Jeeaghyn kiarailagh jeh cre cha mie ta red coadit, noi rolley dy chliaghtey mie.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Smooinaghtyn trooid quoi oddagh brishey stiagh er red, kys, as cre yinnagh oo dy lhiettal ad.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"Tra ta fysseree preevaadjagh cheet magh gys sleih nagh lhisagh eh ve oc, ny ta eh caillit ny caghlaait gyn kied.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Data persoonagh","text":"Fysseree erbee mychione peiagh oddys ve er enney, goll rish ennym, enmys post-l ny ynnyd. Enmyssit myrgeddin PII.","also":["PII","personally identifiable information","personal data"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Yn leigh Oarpagh mychione data persoonagh (ta e lhieggan hene ec y Reeriaght Unnaneysit): chaglym agh ny ta feme ort er, freayll eh sauchey, as lhig da sleih yn data oc y akin ny y scryssey.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Coadey data","text":"Kiarail son data persoonagh dy kiart as cordail rish y leigh.","also":["data protection","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy (reillys preevaadjys)","text":"Duillag phublick ta gra cre'n data persoonagh t'ou chaglym, cre'n fa, as cre t'ou jannoo lesh.","also":["privacy policy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent (coardail)","text":"Yn “ta” baghtal as seyr ta peiagh cur dy vod e data ve ymmydit er aght er lheh. Foddee ad goaill eh er-ash traa erbee.","also":["opt-in","consent"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"Coadan beg ta ynnyd-eggey sauail ayns dty vrawseyr dy chooinaghtyn er reddyn, goll rish dy vel oo loggit stiagh. Ta feme er dty choardail son paart jeu hoshiaght.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Chaglym as freayll agh y data persoonagh ta feer feme ort er son yn obbyr.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"Cre cha liauyr ta data freayllit roish my vel eh scryssit. Ta freayll eh gyn ve ny s'liauyr na ta feme ny s'sauchey, as dy mennick shen y leigh.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Caghlaa data son nagh vod peiagh erbee ve er enney ass ny sodjey, er aght resoonagh.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Cur coadyn ayns ynnyd ennymyn as mynphoyntyn elley, lesh ogher freayllit scarrit dy chiangley ad er-ash. T'eh foast data persoonagh.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"Conaant ta gra kys oddys supplier data persoonagh y reaghey er dty hon.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"Jeeaghyn kiarailagh, roish my vel oo goaill toshiaght, er kys oddagh plan dy ymmyd y yannoo jeh data persoonagh bentyn rish sleih, as kys dy injillaghey ny gauyn.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"Coontey jeh quoi ren cre as cuin, son dy vod oo scrudeil ny s'anmey cre va jeant.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Geiyrt da ny leighyn, reillyn as standards ta bentyn rhyt, as ve abyl soilshaghey dy vel oo jannoo shen.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Standard eddyr-ashoonagh ta fys mie er son reaghey sauchys fysseree. Foddee companeeyn ve certifit rish.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Coontey Americanagh, scrudeilit liorish scrudeyryn veih cheu-mooie, ta soilshaghey dy vel companee kiarail son data kionneyderyn dy kiart.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Jaagent","text":"AI ta gobbraghey er obbyr er e hon hene: lhaih y code, jannoo caghlaaghyn, roie prowallyn as cur coontey er-ash. Ta'n obbyr echey foast scrudeilit.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"Ny meeryn beggey dy teks ta AI lhaih as screeu, mysh tree kerroo jeh fockle gagh fer. Ta ymmyd AI coontit ayns tokens, myr shen ta ny sloo tokens faagail ny smoo jeh dty phlan.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Sarey beg ta roie er e hon hene ec traa soit, myr sampleyr tra ta seshoon AI goaill toshiaght, son dy vel y possan clashtyn dty ghaghlinyn.","also":["hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Corysyn co-earrooder ta jannoo reddyn ta shin dy cadjin smooinaghtyn ta feme er peiagh er, goll rish screeu, freggyrt feyshtyn ny enney y ghoaill er pictyryn.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"Aght dy chur er co-earrooderyn patranyn y ynsaghey veih ram sampleyn, ayns ynnyd leighyn kiart y chur daue.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"Yn “eanchyn” trenit jeh corys AI, troggit liorish ynsaghey veih earroo mooar dy sampleyn. Ta models er lheh ayns keird, tappeeid as pris.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"Model AI trenit er wheesh mooar dy teks, myr shen dy vod eh chengey y lhaih as y screeu.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI ta croo reddyn noa, goll rish teks, pictyryn ny code, cha nee agh reddyn y reaghey ny y akin.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Clare t'ou taggloo rish ayns chengey cadjin, liorish screeu ny loayrt.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Ny t'ou cur da AI: dty eysht ny dty haraghyn, as nhee erbee elley t'ou cur da. Ta prompts ny s'baghtal dy cadjin geddyn freggyrtyn ny share.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"Yn keird dy screeu prompts ta cur eiyrtyssyn ymmydagh as shickyr."},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Saraghyn cooylloo ta AI geddyn roish my vel y taggloo goaill toshiaght, soiaghey e ayrn as e leighyn. T'ad ny smoo trome na ny t'ou screeu.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Dy chooilley nhee oddys yn AI fakin choud as t'eh gobbraghey: ny saraghyn, dty haghteraghtyn, coadanyn t'eh er lhaih as freggyrtyn roie.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"Wheesh oddys AI y reayll ayns e chooinaghtyn ec y traa cheddin, towsit ayns tokens. Harrish shen, ta ny ayrnyn s'shinney faagit magh ny giarit sheese.","also":["context windows"]},{"id":"session","g":"ai","word":"Seshoon","text":"Un taggloo obbyr rish AI, veih toshiaght gys jerrey. Ta seshoon noa goaill toshiaght lesh cooinaghtyn glen.","also":["sessions","session"],"noTip":1},{"id":"memory","g":"ai","word":"Cooinaghtyn","text":"Noteyn ta AI freayll eddyr seshoonyn, son dy vel eh cooinaghtyn er ny reddyn s'mie lhiat as er briwnyssyn roie.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"Tra ta AI gra red ta jeeaghyn feer shickyr jeh hene agh t'eh jeant seose ny rongagh. Scrudee ny reddyn scanshoil.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Trenal","text":"Ynsaghey model liorish earroo mooar dy sampleyn y hoilshaghey da, roish my vel peiagh erbee jannoo ymmyd jeh.","also":["trained","training"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Data trenal","text":"Ny sampleyn ren model ynsaghey voue. Ta'n fys echey scuirr ec y laa va'n data shen er ny haglym.","also":["training set","training data"]},{"id":"cutoff","g":"ai","word":"Laa jerrey yn fys","text":"Yn laa ta'n fys ta troggit stiagh ayns AI cheet gys jerrey. Cha bee fys echey er reddyn ny s'anmey mannagh jean eh shirrey orroo.","also":["training cutoff","knowledge cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Trenal sodjey er model t'ayn hannah lesh dty hampleyn hene, dy yannoo eh ny share son un obbyr er lheh.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"Model AI ta ymmydit dy feer dy reggyrt red, cha nee ve trenit.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"AI ta abyl reddyn y yannoo, cha nee agh loayrt: roie saraghyn, lhaih coadanyn ny shirrey er yn eddyr-voggyl, trooid greieyn ta'n app cur da.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"AI cooney ta AI mooar cur obbyr ny sloo da, as geddyn yn eiyrtys er-ash voish.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Ram AI gobbraghey cooidjagh er un obbyr, gagh fer lesh e ayrn hene, goll rish possan beg.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"Wheesh oddys AI y yannoo er e hon hene roish my shegin da feysht y chur er peiagh.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Freayll peiagh bentyn rish dy scrudeil ny dy choardail ny ta'n AI jannoo ec poyntyn scanshoil. Ayns AI-gile, shen uss.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Cagliaghyn as prowallyn ta freayll ny ta AI jannoo sauchey, goll rish feme er coardail roish my vel nhee erbee goll bio. T'ad injillaghey gaue marranyn, agh cha vel ad cur ad ersooyl dy slane.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Lhiggey da AI reddyn y hirrey ayns dty ghocumaidyn hene roish my vel eh freggyrt, son dy vel ny freggyrtyn echey bunnit er dty reddyn feer hene.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Chyndaa teks gys rolley dy earrooyn ta goaill stiagh e keeall, son dy vod co-earrooder reddyn y gheddyn lesh keeall cosoylagh.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"Database troggit dy hirrey ny rolleyn shen dy earrooyn (embeddings), dy gheddyn cooid lesh keeall cosoylagh.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Aght cadjin dy chiangley greieyn as bun-fysseree rish apps AI, son dy vod AI ymmyd y yannoo jeu.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"Soiaghey son cre cha dunnal as ta freggyrtyn AI. Ta injil cur freggyrtyn ny s'kiune as ny smoo ry-akin roish laue; ta ard cur freggyrtyn ny smoo caghlaaghagh. Cha vel nane jeu cur er dy ve kinjagh kiart.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Abyl dy obbraghey lesh ny smoo na un sorch dy fysseree, goll rish teks, pictyryn as sheean.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"Prowal plannit jeh cre cha mie ta AI jannoo er sampleyn reiht, son dy vod oo models ny prompts y chosoylaghey.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Bias","text":"Tra ta AI (ny peiagh) croymmey dy neu-chairal gys un cheu, dy mennick kyndagh rish ny ren eh ynsaghey voue.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Ymmyd y yannoo jeh AI dy cairal, dy sauchey as dy onnoroil, lesh sleih foast freggyrtagh son ny eiyrtyssyn.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"Kialg raad ta saraghyn follit ayns duillag eggey ny coadan prowal er AI red y yannoo nagh ren e ymmydeyr shirrey.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"Cagliagh er whilleen aghin oddys oo cur gys shirveish ayns traa soit. Gow harrish as shegin dhyt fuirraght.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"Wheesh obbyr AI ta dty phlan lhiggey ayns tammylt, as lurg shen t'eh scuirr son tammylt ny costal ny smoo.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Troggal software er y chooid smoo liorish insh da AI cre t'ou geearree as lhiggey da'n code y screeu.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budjet","text":"Yn argid ta currit er-lhimmey son red.","also":["budjetyn","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Tomys cost","text":"Yn tomys s'share er cre vees red dy chostal roish my vel oo goaill toshiaght.","also":["cost estimates","cost estimate"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"Ny t'ou geddyn er-ash cosoylit rish ny t'ou cur stiagh. My ta ny smoo cheet er-ash, v'eh feeu.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Dy chooilley nhee ta red dy feer dy chostal rish e vea slane, cha nee agh y pris dy chionnaghey: eh y roie, cooney, noaghaghyn as eh y scuirr ec y jerrey.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx as OpEx","text":"Ta CapEx argid ceaut roish laue er reddyn t'ou freayll; ta OpEx ceau dy kinjagh, goll rish bilyn gagh mee.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Eeck dy kinjagh, dy cadjin gagh mee ny gagh blein, dy gholl er dy ymmyd y yannoo jeh red.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software t'ou jannoo ymmyd jeh er-linney as eeck er liorish subscription, choud as ta'n fer-croo dy roie eh er dty hon.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Eeck agh son ny t'ou jannoo ymmyd jeh, goll rish cloud computing ny tokens AI.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Ymmyd harrish ny ta dty phlan goaill stiagh, as foddee shen costal ny smoo.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"Çhaghteraght tra ta ceau ny ymmyd roshtyn y cheim ren oo reih. T'eh cur raaue dhyt, agh cha vel eh kinjagh lhiettal costyn sodjey.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"Keim nastee jeh shirveish ta costal, lesh cagliaghyn. Ymmydagh dy ghoaill toshiaght.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"Ny pakkadyn er lheh ta shirveish dy chreck, gagh fer lesh e phris as e chagliaghyn hene.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Kied","text":"Ny leighyn mychione kys oddys oo ymmyd y yannoo jeh, coipey, caghlaa ny rheynn red ren peiagh elley, goll rish software, fonts ny pictyryn.","also":["licences","license","licenses","licence"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software ta'n code echey foshlit da peiagh erbee dy lhaih, dy ymmyd as dy mennick dy chaghlaa nastee, fo leighyn yn kied echey.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Kied open source","text":"Ny leighyn ta cheet lesh code open source. Ta paart lhiggey dhyt bunnys nhee erbee y yannoo (goll rish MIT); ta paart shirrey ort dty chaghlaaghyn y rheynn myrgeddin (goll rish GPL).","also":["open source licence","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Lesh companee, as cha nel eh seyr dy choipey ny dy chaghlaa. Yn red noi open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"Yn cairys leighal ec fer-croo dy reaghey coipyn jeh e obbyr, cooidjagh rish code as screeuyn.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Smooinaghtyn as reddyn crooit ta'n leigh coontey myr cooid peiagh ennagh, goll rish code, designyn, ennymyn as logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"Ny leighyn t'ou coardail roo tra t'ou jannoo ymmyd jeh shirveish.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Conaant","text":"Coardail screeuit eddyr daa heu, as ta'n leigh dy chooney lesh.","also":["contracts","contract"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"Documaid ta soiaghey magh dy shickyr cre'n obbyr vees jeant, roish cuin, as son cre'n pris.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Pris soit","text":"Pris coardit son yn obbyr slane, cre erbee cha liauyr as t'eh goaill.","also":["fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Traa as cooid","text":"Eeck son ny ooryn va feer obbrit as ny reddyn va feer ymmydit, ayns ynnyd pris soit.","also":["T&M","time and materials"]},{"id":"invoice","g":"money","word":"Invoice","text":"Bil ta shirrey eeck son obbyr jeant ny cooid currit.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"Tra ta goll ersooyl veih supplier cha doillee ny cha costal dy vel oo kiangit roo.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"Yn aght dy reih as dy chionnaghey veih suppliers."},{"id":"servicecredit","g":"money","word":"Service credit","text":"Argid er-ash ny pris ny sloo t'ou geddyn tra ta supplier failleil er e SLA.","also":["service credits"]}]}};
